   103	static int start_adv_cmd(void* handle, int argc, char* argv[])
   104	{
   105	    uint8_t adv_mode = 0;
   106	    ble_adv_params_t params = { 0 };
   107	    advertiser_data_t *adv = NULL, *scan_rsp = NULL;
   108	    uint8_t *p_adv_data = NULL, *p_scan_rsp_data = NULL;
   109	    uint16_t adv_len, scan_rsp_len;
   110	    bt_advertiser_t* adv_handle;
   111	    char* name = "VELA_BT";
   112	    uint16_t appearance = 0;
   113	    int opt;
   114	
   115	    params.adv_type = BT_LE_ADV_IND;
   116	    bt_addr_set_empty(&params.peer_addr);
   117	    params.peer_addr_type = BT_LE_ADDR_TYPE_PUBLIC;
   118	    bt_addr_set_empty(&params.own_addr);
   119	    params.own_addr_type = BT_LE_ADDR_TYPE_PUBLIC;
   120	    params.interval = 320;
   121	    params.tx_power = 0;
   122	    params.channel_map = BT_LE_ADV_CHANNEL_DEFAULT;
   123	    params.filter_policy = BT_LE_ADV_FILTER_WHITE_LIST_FOR_NONE;
   124	    params.duration = 0;
   125	
   126	    optind = 0;
   127	    while ((opt = getopt_long(argc, argv, "+t:m:i:n:a:p:c:f:d:P:T:O:R:D", adv_options,
   128	                NULL))
   129	        != -1) {
   130	        switch (opt) {
   131	        case 't':
   132	            if (strncasecmp(optarg, "adv_ind", strlen("adv_ind")) == 0)
   133	                params.adv_type = BT_LE_ADV_IND;
   134	            else if (strncasecmp(optarg, "direct_ind", strlen("direct_ind")) == 0)
   135	                params.adv_type = BT_LE_ADV_DIRECT_IND;
   136	            else if (strncasecmp(optarg, "nonconn_ind", strlen("nonconn_ind")) == 0)
   137	                params.adv_type = BT_LE_ADV_NONCONN_IND;
   138	            else if (strncasecmp(optarg, "scan_ind", strlen("scan_ind")) == 0)
   139	                params.adv_type = BT_LE_ADV_SCAN_IND;
   140	            else if (strncasecmp(optarg, "scan_rsp_ind", strlen("scan_rsp_ind")) == 0)
   141	                params.adv_type = BT_LE_SCAN_RSP;
   142	            else {
   143	                PRINT("error adv type: %s", optarg);
   144	                return CMD_INVALID_PARAM;
   145	            }
   146	
   147	            PRINT("adv type: %s", optarg);
   148	            break;
   149	        case 'm':
   150	            if (strncasecmp(optarg, "legacy", strlen("legacy")) == 0)
   151	                adv_mode = 1;
   152	            else if (strncasecmp(optarg, "ext", strlen("ext")) == 0)
   153	                adv_mode = 2;
   154	            else if (strncasecmp(optarg, "auto", strlen("auto")) == 0)
   155	                adv_mode = 0;
   156	            else {
   157	                PRINT("erro adv mode: %s", optarg);
   158	                return CMD_INVALID_PARAM;
   159	            }
   160	
   161	            PRINT("adv type: %s", optarg);
   162	            break;
   163	        case 'i': {
   164	            int32_t interval = atoi(optarg);
   165	            if (interval < 0x20 || interval > 0x4000) {
   166	                PRINT("error interval, range must in 0x20~0x4000");
   167	                return CMD_INVALID_PARAM;
   168	            }
   169	
   170	            params.interval = interval;
   171	            PRINT("interval: %f ms", (float)interval * 0.625);
   172	        } break;
   173	        case 'n': {
   174	            name = optarg;
   175	            PRINT("adv name: %s ", optarg);
   176	        } break;
   177	        case 'a': {
   178	            appearance = strtol(optarg, NULL, 16);
   179	            PRINT("adv appearance: 0x%04x ", appearance);
   180	        }
   285	    }
   286	
   287	    if (params.own_addr_type == BT_LE_ADDR_TYPE_RANDOM && bt_addr_is_empty(&params.own_addr)) {
   288	        PRINT("should set own address using \"-O\" option");
   289	        return CMD_INVALID_ADDR;
   290	    }
   291	
   292	    if (adv_mode == 1)
   293	        params.adv_type += BT_LE_LEGACY_ADV_IND;
   294	    else if (adv_mode == 2)
   295	        params.adv_type += BT_LE_EXT_ADV_IND;
   296	
   297	    if (!p_adv_data) {
   298	        bt_uuid_t uuid;
   299	
   300	        adv = advertiser_data_new();
   301	
   302	        /* set adv flags 0x08 */
   303	        advertiser_data_set_flags(adv, BT_AD_FLAG_DUAL_MODE | BT_AD_FLAG_GENERAL_DISCOVERABLE);
   304	
   305	        /* add spp uuid */
   306	        bt_uuid16_create(&uuid, 0x1101);
   307	        advertiser_data_add_service_uuid(adv, &uuid);
   308	
   309	        /* add handsfree uuid */
   310	        bt_uuid16_create(&uuid, 0x111E);
   311	        advertiser_data_add_service_uuid(adv, &uuid);
   312	
   313	        /* set adv appearance */
   314	        if (appearance)
   315	            advertiser_data_set_appearance(adv, appearance);
   316	
   317	        /* build adverser data */
   318	        p_adv_data = advertiser_data_build(adv, &adv_len);
   319	
   320	        scan_rsp = advertiser_data_new();
   321	
   322	        /* set adv complete name */
   323	        advertiser_data_set_name(scan_rsp, name);
   324	
   325	        /* build scan response data */
   326	        p_scan_rsp_data = advertiser_data_build(scan_rsp, &scan_rsp_len);
   327	    }
   328	
   329	    if (p_adv_data)
   330	        advertiser_data_dump(p_adv_data, adv_len, NULL);
   331	
   332	    if (p_scan_rsp_data)
   333	        advertiser_data_dump(p_scan_rsp_data, scan_rsp_len, NULL);
   334	
   335	    adv_handle = bt_le_start_advertising(handle, &params,
   336	        p_adv_data, adv_len,
   337	        p_scan_rsp_data, scan_rsp_len,
   338	        &adv_callback);
   339	
   340	    PRINT("Advertising handle:%p", adv_handle);
   341	    /* free advertiser data */
   342	    if (adv)
   343	        advertiser_data_free(adv);
   344	
   345	    /* free scan response data */
   346	    if (scan_rsp)
   347	        advertiser_data_free(scan_rsp);
   348	
   349	    return CMD_OK;
   350	}
