   808	static int start_advertising(void)
   809	{
   810	  ble_adv_params_t params;
   811	
   812	  if (g_advertiser != NULL)
   813	    {
   814	      return 0;
   815	    }
   816	
   817	  memset(&params, 0, sizeof(params));
   818	  params.adv_type = BT_LE_LEGACY_ADV_IND;
   819	  params.interval = 320;
   820	  params.duration = 0;
   821	  params.channel_map = BT_LE_ADV_CHANNEL_DEFAULT;
   822	  params.filter_policy = BT_LE_ADV_FILTER_WHITE_LIST_FOR_NONE;
   823	
   824	  if (g_adv_data == NULL || g_scan_rsp_data == NULL)
   825	    {
   826	      g_adv_data = advertiser_data_new();
   827	      g_scan_rsp_data = advertiser_data_new();
   828	      if (g_adv_data == NULL || g_scan_rsp_data == NULL)
   829	        {
   830	          printf("openvela_ble_probe: advertiser_data_new failed\n");
   831	          return -1;
   832	        }
   833	
   834	      advertiser_data_set_flags(g_adv_data,
   835	                                BT_AD_FLAG_GENERAL_DISCOVERABLE |
   836	                                BT_AD_FLAG_BREDR_NOT_SUPPORT);
   837	      advertiser_data_set_name(g_scan_rsp_data, "ov_ble_probe");
   838	
   839	      g_adv_payload = advertiser_data_build(g_adv_data,
   840	                                            &g_adv_payload_len);
   841	      g_scan_rsp_payload = advertiser_data_build(g_scan_rsp_data,
   842	                                                 &g_scan_rsp_payload_len);
   843	      if (g_adv_payload == NULL || g_scan_rsp_payload == NULL)
   844	        {
   845	          printf("openvela_ble_probe: advertiser_data_build failed\n");
   846	          return -1;
   847	        }
   848	    }
   849	
   850	  g_advertiser = bt_le_start_advertising(g_instance, &params,
   851	                                         g_adv_payload, g_adv_payload_len,
   852	                                         g_scan_rsp_payload,
   853	                                         g_scan_rsp_payload_len,
   854	                                         &g_advertiser_callbacks);
   855	  if (g_advertiser == NULL)
   856	    {
   857	      printf("openvela_ble_probe: bt_le_start_advertising failed\n");
   858	      return -1;
   859	    }
   860	
   861	  printf("openvela_ble_probe: advertising as ov_ble_probe\n");
   862	  return 0;
   863	}
