   549	static void STACK_CALL(stop_adv)(void* args)
   550	{
   551	    sal_adapter_req_t* req = args;
   552	    struct bt_le_adv_set* adv_set;
   553	    int ret;
   554	    bool ext_supported;
   555	
   556	    ext_supported = bt_le_ext_adv_is_supported();
   557	
   558	    if (!ext_supported) {
   559	        ret = bt_le_adv_stop();
   560	        if (ret) {
   561	            BT_LOGE("%s, legacy adv stop fail", __func__);
   562	            return;
   563	        } else {
   564	            goto stopped;
   565	        }
   566	    }
   567	
   568	    adv_set = zblue_le_ext_find_adv(req->adv_id);
   569	    if (!adv_set) {
   570	        BT_LOGE("%s, le ext adv_set find fail", __func__);
   571	        return;
   572	    }
   573	
   574	    ret = bt_le_ext_adv_stop(adv_set->adv);
   575	    if (ret) {
   576	        BT_LOGE("%s, le ext adv stop fail", __func__);
   577	        return;
   578	    }
   579	
   580	    ret = zblue_le_ext_delete(adv_set);
   581	    if (ret) {
   582	        BT_LOGE("%s, le ext adv stop fail", __func__);
   583	        return;
   584	    }
   585	
   586	stopped:
   587	    advertising_on_state_changed(req->adv_id, LE_ADVERTISING_STOPPED);
   588	}
