   479	    if (!req) {
   480	        BT_LOGE("%s, req null", __func__);
   481	        return BT_STATUS_NOMEM;
   482	    }
   483	
   484	    ret = zblue_le_ext_convert_param(params, &req->adpt.start_adv.param);
