    70	static void advertiser_info_free(advertising_info_t* adv_info)
    71	{
    72	    if (adv_info) {
    73	        if (adv_info->adv_data)
    74	            free(adv_info->adv_data);
    75	        if (adv_info->scan_rsp_data)
    76	            free(adv_info->scan_rsp_data);
    77	        free(adv_info);
    78	    }
    79	}
    80	
    81	static advertising_info_t* advertiser_info_copy(ble_adv_params_t* params,
    82	    uint8_t* adv_data,
    83	    uint16_t adv_len,
    84	    uint8_t* scan_rsp_data,
    85	    uint16_t scan_rsp_len)
    86	{
    87	    advertising_info_t* adv_info = calloc(1, sizeof(advertising_info_t));
    88	    if (!adv_info)
    89	        goto fail;
    90	
    91	    if (adv_len && adv_data) {
    92	        adv_info->adv_data = malloc(adv_len);
    93	        if (!adv_info->adv_data)
    94	            goto fail;
    95	        memcpy(adv_info->adv_data, adv_data, adv_len);
    96	        adv_info->adv_len = adv_len;
    97	    }
    98	
    99	    if (scan_rsp_len && scan_rsp_data) {
   100	        adv_info->scan_rsp_data = malloc(scan_rsp_len);
   101	        if (!adv_info->scan_rsp_data)
   102	            goto fail;
   103	        memcpy(adv_info->scan_rsp_data, scan_rsp_data, scan_rsp_len);
   104	        adv_info->scan_rsp_len = scan_rsp_len;
   105	    }
   106	    memcpy(&adv_info->params, params, sizeof(ble_adv_params_t));
   107	
   108	    return adv_info;
   109	fail:
   110	    advertiser_info_free(adv_info);
   111	    return NULL;
   112	}
