   311	bt_advertiser_t* start_advertising(void* remote,
   312	    ble_adv_params_t* params,
   313	    uint8_t* adv_data,
   314	    uint16_t adv_len,
   315	    uint8_t* scan_rsp_data,
   316	    uint16_t scan_rsp_len,
   317	    const advertiser_callback_t* cbs)
   318	{
   319	    if (!adapter_is_le_enabled())
   320	        return NULL;
   321	
   322	    advertiser_t* adver = alloc_new_advertiser(remote, cbs);
   323	    if (!adver)
   324	        return NULL;
   325	
   326	    adv_event_t* start = malloc(sizeof(adv_event_t));
   327	    if (!start) {
   328	        destroy_advertiser(adver);
   329	        return NULL;
   330	    }
   331	
   332	    start->adver = adver;
   333	    start->adv_info = advertiser_info_copy(params, adv_data, adv_len,
   334	        scan_rsp_data, scan_rsp_len);
   335	    do_in_service_loop(advertiser_start_event, start);
   336	
   337	    return (bt_advertiser_t*)adver;
   338	}
