    82	static bt_status_t parse_bt_adv_data(uint8_t* raw, uint16_t raw_len,
    83	    struct bt_data* out, size_t out_max, size_t* out_size)
    84	{
    85	    size_t index;
    86	    uint8_t item_len;
    87	
    88	    if (!out || !out_size || out_max == 0) {
    89	        return BT_STATUS_PARM_INVALID;
    90	    }
    91	
    92	    *out_size = 0;
    93	
    94	    if (!raw || raw_len == 0) {
    95	        return BT_STATUS_SUCCESS;
    96	    }
    97	
    98	    for (index = 0; index < raw_len;) {
    99	        item_len = raw[index];
   100	        if (item_len == 0) {
   101	            break;
   102	        }
   103	
   104	        if (item_len < 2) {
   105	            BT_LOGE("%s, invalid adv data item len:%d", __func__, item_len);
   106	            return BT_STATUS_PARM_INVALID;
   107	        }
   108	
   109	        if (index + 1 + item_len > raw_len) {
   110	            BT_LOGE("%s, adv data overflow: raw_len=%d idx=%d item_len=%d", __func__,
   111	                raw_len, index, item_len);
   112	            return BT_STATUS_PARM_INVALID;
   113	        }
   114	
   115	        if (*out_size >= out_max) {
   116	            BT_LOGE("too many segments: out_max=%d idx=%d", out_max, index);
   117	            return BT_STATUS_PARM_INVALID;
   118	        }
   119	
   120	        out[*out_size].data_len = item_len - 1;
   121	        out[*out_size].type = raw[index + 1];
   122	        out[*out_size].data = &raw[index + 2];
   123	        index += out[*out_size].data_len + 2;
   124	        (*out_size)++;
   125	    }
   126	
   127	    return BT_STATUS_SUCCESS;
   128	}
