   130	static void ext_adv_terminated_cb(struct bt_le_ext_adv* adv)
   131	{
   132	    struct bt_le_adv_set* adv_set;
   133	    sal_adapter_req_t* req;
   134	    int index;
   135	
   136	    BT_LOGD("%s ", __func__);
   137	
   138	    index = bt_le_ext_adv_get_index(adv);
   139	    adv_set = g_adv_sets[index];
   140	    if (!adv_set) {
   141	        BT_LOGE("%s, adv set index:%d null", __func__, index);
   142	        return;
   143	    }
   144	
   145	    if (adv_set->delete_pending) {
   146	        return;
   147	    }
   148	
   149	    adv_set->delete_pending = true;
   150	    req = sal_adapter_req(0, adv_set->adv_id, STACK_CALL(cleanup_terminated_adv));
   151	    if (!req) {
   152	        adv_set->delete_pending = false;
   153	        BT_LOGE("%s, req null", __func__);
   154	        return;
   155	    }
   156	
   157	    BT_LOGD("sal adv: defer terminated cleanup id=%u", adv_set->adv_id);
   158	    if (sal_send_req(req) != BT_STATUS_SUCCESS) {
   159	        adv_set->delete_pending = false;
   160	    }
   161	}
