   177	static bt_status_t zblue_le_ext_convert_param(ble_adv_params_t* params, struct bt_le_adv_param* param)
   178	{
   179	    static bt_addr_le_t addr;
   180	
   181	    switch (params->adv_type) {
   182	    case BT_LE_ADV_IND:
   183	    case BT_LE_EXT_ADV_IND:
   184	        param->options |= BT_LE_ADV_OPT_CONN;
   185	        param->options |= BT_LE_ADV_OPT_EXT_ADV;
   186	        param->options |= BT_LE_ADV_OPT_NO_2M;
   187	        break;
   188	    case BT_LE_ADV_SCAN_IND:
   189	    case BT_LE_EXT_ADV_SCAN_IND:
   190	        param->options |= BT_LE_ADV_OPT_SCANNABLE;
   191	        param->options |= BT_LE_ADV_OPT_EXT_ADV;
   192	        param->options |= BT_LE_ADV_OPT_NO_2M;
   193	        break;
   194	    case BT_LE_ADV_DIRECT_IND:
   195	    case BT_LE_EXT_ADV_DIRECT_IND:
   196	        param->options |= BT_LE_ADV_OPT_CONN;
   197	        param->options |= BT_LE_ADV_OPT_EXT_ADV;
   198	        param->options |= BT_LE_ADV_OPT_NO_2M;
   199	        param->options |= BT_LE_ADV_OPT_DIR_MODE_LOW_DUTY;
   200	        break;
   201	    case BT_LE_SCAN_RSP:
   202	    case BT_LE_EXT_SCAN_RSP:
   203	    case BT_LE_ADV_NONCONN_IND:
   204	    case BT_LE_EXT_ADV_NONCONN_IND:
   205	        param->options |= BT_LE_ADV_OPT_EXT_ADV;
   206	        param->options |= BT_LE_ADV_OPT_NO_2M;
   207	        break;
   208	    case BT_LE_LEGACY_ADV_IND:
   209	        param->options |= BT_LE_ADV_OPT_CONN;
   210	        param->options |= BT_LE_ADV_OPT_SCANNABLE;
   211	        break;
   212	    case BT_LE_LEGACY_ADV_DIRECT_IND:
   213	        param->options |= BT_LE_ADV_OPT_CONN;
   214	        break;
   215	    case BT_LE_LEGACY_ADV_SCAN_IND:
   216	        param->options |= BT_LE_ADV_OPT_SCANNABLE;
   217	        break;
   218	    case BT_LE_LEGACY_ADV_NONCONN_IND:
   219	    case BT_LE_LEGACY_SCAN_RSP:
   220	        break;
   221	    default:
   222	        BT_LOGE("%s, le ext adv convert fail, invalid adv_type:%d", __func__, params->adv_type);
   223	        return BT_STATUS_PARM_INVALID;
   224	    }
   225	
   226	    switch (params->own_addr_type) {
   227	    case BT_LE_ADDR_TYPE_PUBLIC:
   228	        param->options |= BT_LE_ADV_OPT_USE_IDENTITY;
   229	        break;
   230	    }
   231	
   232	    switch (params->channel_map) {
   233	    case BT_LE_ADV_CHANNEL_37_ONLY:
   234	        param->options |= BT_LE_ADV_OPT_DISABLE_CHAN_38 | BT_LE_ADV_OPT_DISABLE_CHAN_39;
   235	        break;
   236	    case BT_LE_ADV_CHANNEL_38_ONLY:
   237	        param->options |= BT_LE_ADV_OPT_DISABLE_CHAN_37 | BT_LE_ADV_OPT_DISABLE_CHAN_39;
   238	        break;
   239	    case BT_LE_ADV_CHANNEL_39_ONLY:
   240	        param->options |= BT_LE_ADV_OPT_DISABLE_CHAN_37 | BT_LE_ADV_OPT_DISABLE_CHAN_38;
   241	        break;
   242	    case BT_LE_ADV_CHANNEL_DEFAULT:
   243	        break;
   244	    default:
   245	        BT_LOGE("%s, le ext adv convert fail, invalid channel_map:%d", __func__, params->channel_map);
   246	        return BT_STATUS_PARM_INVALID;
   247	    }
   248	
   249	    switch (params->filter_policy) {
   250	    case BT_LE_ADV_FILTER_WHITE_LIST_FOR_SCAN:
   251	        param->options |= BT_LE_ADV_OPT_FILTER_SCAN_REQ;
   252	        break;
   253	    case BT_LE_ADV_FILTER_WHITE_LIST_FOR_CONNECTION:
   254	        param->options |= BT_LE_ADV_OPT_FILTER_CONN;
   255	        break;
   256	    case BT_LE_ADV_FILTER_WHITE_LIST_FOR_ALL:
   257	        param->options |= BT_LE_ADV_OPT_FILTER_SCAN_REQ;
   258	        param->options |= BT_LE_ADV_OPT_FILTER_CONN;
   259	        break;
   260	    case BT_LE_ADV_FILTER_WHITE_LIST_FOR_NONE:
   440	            BT_LOGE("%s, le ext adv set fail, err:%d", __func__, ret);
   441	            ret = BT_STATUS_FAIL;
   442	            goto done;
   443	        }
   444	
   445	        ret = bt_le_ext_adv_start(adv, &req->adpt.start_adv.ext_param);
   446	        if (ret) {
   447	            BT_LOGE("%s, le ext adv start fail, err:%d", __func__, ret);
   448	            ret = BT_STATUS_FAIL;
   449	            goto done;
   450	        }
   451	    } else {
   452	        ret = bt_le_adv_start(&req->adpt.start_adv.param, ad_size > 0 ? ad : NULL, ad_size,
   453	            sd_size > 0 ? sd : NULL, sd_size);
   454	        if (ret) {
   455	            BT_LOGE("%s, legacy adv start fail, err:%d", __func__, ret);
