   471	bt_status_t bt_sal_le_start_adv(bt_controller_id_t id, uint8_t adv_id, ble_adv_params_t* params, uint8_t* adv_data, uint16_t adv_len, uint8_t* scan_rsp_data, uint16_t scan_rsp_len)
   472	{
   473	    sal_adapter_req_t* req;
   474	    int ret;
   475	    bool ext_adv;
   476	    bool ext_supported;
   477	
   478	    req = sal_adapter_req(id, adv_id, STACK_CALL(start_adv));
   479	    if (!req) {
   480	        BT_LOGE("%s, req null", __func__);
   481	        return BT_STATUS_NOMEM;
   482	    }
   483	
   484	    ret = zblue_le_ext_convert_param(params, &req->adpt.start_adv.param);
   485	    if (ret) {
   486	        BT_LOGE("%s, le ext adv convert fail, err:%d", __func__, ret);
   487	        ret = BT_STATUS_PARM_INVALID;
   488	        goto error;
   489	    }
   490	
   491	    ext_supported = bt_le_ext_adv_is_supported();
   492	    ext_adv = (req->adpt.start_adv.param.options & BT_LE_ADV_OPT_EXT_ADV) ? true : false;
   493	
   494	    if (ext_adv && !ext_supported) {
   495	        BT_LOGE("%s, controller not support ext adv", __func__);
   496	        ret = BT_STATUS_UNSUPPORTED;
   497	        goto error;
   498	    }
   499	
   500	    if (((!(req->adpt.start_adv.param.options & BT_LE_ADV_OPT_SCANNABLE) && ext_adv)
   501	            || !ext_adv)
   502	        && adv_data && adv_len > 0) {
   503	        req->adpt.start_adv.adv_data = malloc(adv_len);
   504	        if (!req->adpt.start_adv.adv_data) {
   505	            BT_LOGE("%s, malloc fail", __func__);
   506	            ret = BT_STATUS_NOMEM;
   507	            goto error;
   508	        }
   509	
   510	        memcpy(req->adpt.start_adv.adv_data, adv_data, adv_len);
   511	        req->adpt.start_adv.adv_len = adv_len;
   512	    } else {
   513	        req->adpt.start_adv.adv_data = NULL;
   514	        req->adpt.start_adv.adv_len = 0;
   515	    }
   516	
   517	    if ((((req->adpt.start_adv.param.options & BT_LE_ADV_OPT_SCANNABLE) && ext_adv)
   518	            || !ext_adv)
   519	        && scan_rsp_data && scan_rsp_len > 0) {
   520	        req->adpt.start_adv.scan_rsp_data = malloc(scan_rsp_len);
   521	        if (!req->adpt.start_adv.scan_rsp_data) {
   522	            BT_LOGE("%s, malloc fail", __func__);
   523	            ret = BT_STATUS_NOMEM;
   524	            goto error;
   525	        }
   526	
   527	        memcpy(req->adpt.start_adv.scan_rsp_data, scan_rsp_data, scan_rsp_len);
   528	        req->adpt.start_adv.scan_rsp_len = scan_rsp_len;
   529	    } else {
   530	        req->adpt.start_adv.scan_rsp_data = NULL;
   531	        req->adpt.start_adv.scan_rsp_len = 0;
   532	    }
   533	
   534	    if (params->duration) {
   535	        req->adpt.start_adv.ext_param.timeout = params->duration;
   536	    }
   537	
   538	    return sal_send_req(req);
   539	
   540	error:
   541	    if (req->adpt.start_adv.adv_data)
   542	        free(req->adpt.start_adv.adv_data);
   543	    if (req->adpt.start_adv.scan_rsp_data)
   544	        free(req->adpt.start_adv.scan_rsp_data);
   545	    free(req);
