   404	static void STACK_CALL(start_adv)(void* args)
   405	{
   406	    sal_adapter_req_t* req = args;
   407	    struct bt_le_ext_adv* adv;
   408	    int ret;
   409	    struct bt_data ad[CONFIG_BT_EXT_ADV_MAX_ADV_SEGMENT] = { 0 };
   410	    struct bt_data sd[CONFIG_BT_EXT_ADV_MAX_ADV_SEGMENT] = { 0 };
   411	    size_t ad_size = 0;
   412	    size_t sd_size = 0;
   413	    bool ext_supported = bt_le_ext_adv_is_supported();
   414	
   415	    ret = parse_bt_adv_data(req->adpt.start_adv.adv_data, req->adpt.start_adv.adv_len,
   416	        ad, ARRAY_SIZE(ad), &ad_size);
   417	    if (ret) {
   418	        BT_LOGE("%s, parse adv_data fail, err:%d", __func__, ret);
   419	        goto done;
   420	    }
   421	
   422	    ret = parse_bt_adv_data(req->adpt.start_adv.scan_rsp_data, req->adpt.start_adv.scan_rsp_len,
   423	        sd, ARRAY_SIZE(sd), &sd_size);
   424	    if (ret) {
   425	        BT_LOGE("%s, parse scan_rsp_data fail, ret:%d", __func__, ret);
   426	        goto done;
   427	    }
   428	
   429	    if (ext_supported) {
   430	        ret = zblue_le_ext_create(&req->adpt.start_adv.param, &adv, req->adv_id);
   431	        if (ret) {
   432	            BT_LOGE("%s, zblue le ext adv create fail, err:%d", __func__, ret);
   433	            ret = BT_STATUS_FAIL;
   434	            goto done;
   435	        }
   436	
   437	        ret = bt_le_ext_adv_set_data(adv, ad_size > 0 ? ad : NULL, ad_size,
   438	            sd_size > 0 ? sd : NULL, sd_size);
   439	        if (ret) {
   440	            BT_LOGE("%s, le ext adv set fail, err:%d", __func__, ret);
   441	            ret = BT_STATUS_FAIL;
   442	            goto done;
   443	        }
   444	
   445	        ret = bt_le_ext_adv_start(adv, &req->adpt.start_adv.ext_param);
   446	        if (ret) {
   447	            BT_LOGE("%s, le ext adv start fail, err:%d", __func__, ret);
   448	            ret = BT_STATUS_FAIL;
   449	            goto done;
   450	        }
   451	    } else {
   452	        ret = bt_le_adv_start(&req->adpt.start_adv.param, ad_size > 0 ? ad : NULL, ad_size,
   453	            sd_size > 0 ? sd : NULL, sd_size);
   454	        if (ret) {
   455	            BT_LOGE("%s, legacy adv start fail, err:%d", __func__, ret);
   456	            ret = BT_STATUS_FAIL;
   457	            goto done;
   458	        }
   459	    }
   460	
   461	    advertising_on_state_changed(req->adv_id, LE_ADVERTISING_STARTED);
   462	    ret = BT_STATUS_SUCCESS;
   463	
   464	done:
   465	    if (req->adpt.start_adv.adv_data)
   970		if (!adv_is_directed(adv)) {
   971			conn = bt_conn_lookup_state_le(adv->hdev, adv->id, BT_ADDR_LE_NONE,
   972						       BT_CONN_ADV_CONNECTABLE);
   973		} else {
   974			conn = bt_conn_lookup_state_le(adv->hdev, adv->id, &adv->target_addr,
   975						       BT_CONN_ADV_DIR_CONNECTABLE);
   976		}
   977	
   978		if (conn) {
   979			conn->err = status;
   980			bt_conn_set_state(conn, BT_CONN_DISCONNECTED);
   981			bt_conn_unref(conn);
   982		}
   983	}
