		err = bt_id_set_adv_own_addr(adv, options, dir_adv, &own_addr_type);
		if (err) {
			LOG_ERR("Controller cannot resume connectable advertising (%d)", err);
			return;
		}
	}

	err = bt_le_adv_set_enable(adv, true);
	if (err) {
		LOG_DBG("Controller cannot resume connectable advertising (%d)", err);
		bt_conn_set_state(conn, BT_CONN_DISCONNECTED);

		/* Temporarily clear persist flag to avoid recursion in
		 * bt_conn_unref if the flag is still set.
		 */
		persist_paused = atomic_test_and_clear_bit(adv->flags,
							   BT_ADV_PERSIST);
	}

	/* Since we don't give the application a reference to manage in
	 * this case, we need to release this reference here.
	 */
	bt_conn_unref(conn);
	if (persist_paused) {
		atomic_set_bit(adv->flags, BT_ADV_PERSIST);
	}
}
#endif /* defined(CONFIG_BT_PERIPHERAL) */

bool bt_le_ext_adv_is_supported_mc(uint8_t dev_id)
{
	struct bt_dev *hdev = bt_dev_get(dev_id);

	if (!hdev) {
		return false;
	}

	if (!IS_ENABLED(CONFIG_BT_EXT_ADV)) {
		return false;
	}

	return BT_DEV_FEAT_LE_EXT_ADV(hdev->le.features);
}

#if defined(CONFIG_BT_EXT_ADV)
int bt_le_ext_adv_get_info(const struct bt_le_ext_adv *adv,
			   struct bt_le_ext_adv_info *info)
{
	info->id = adv->id;
	info->tx_power = adv->tx_power;
	info->addr = &adv->random_addr;

	return 0;
}

int bt_le_ext_adv_create_mc(uint8_t dev_id, const struct bt_le_adv_param *param,
			 const struct bt_le_ext_adv_cb *cb,
			 struct bt_le_ext_adv **out_adv)
{
	struct bt_le_ext_adv *adv;
	int err;
	struct bt_dev *hdev;
	bool diag = ov_ble_adv_diag_param(param);

	if (diag) {
		syslog(LOG_INFO, "ov_ble_adv_diag: zblue adv: create begin\n");
	}

	hdev = bt_dev_get(dev_id);
	if (!hdev) {
		if (diag) {
			syslog(LOG_INFO, "ov_ble_adv_diag: zblue adv: create returned status=%d\n", -ENODEV);
		}
		return -ENODEV;
	}

	if (!atomic_test_bit(hdev->flags, BT_DEV_READY)) {
		if (diag) {
			syslog(LOG_INFO, "ov_ble_adv_diag: zblue adv: create returned status=%d\n", -EAGAIN);
		}
		return -EAGAIN;
	}

	if (!valid_adv_ext_param(hdev, param)) {
		if (diag) {
			syslog(LOG_INFO, "ov_ble_adv_diag: zblue adv: create returned status=%d\n", -EINVAL);
		}
		return -EINVAL;
	}

	if (ZBLUE_FORCE_LEGACY_HCI_FOR_LEGACY_ADV &&
	    !(param->options & BT_LE_ADV_OPT_EXT_ADV) &&
	    (param->options & _BT_LE_ADV_OPT_CONNECTABLE) &&
	    (param->options & BT_LE_ADV_OPT_SCANNABLE)) {
		err = adv_create_legacy(hdev);
		if (err) {
			return err;
		}

		adv = bt_le_adv_lookup_legacy(hdev);
		adv->id = param->id;
		adv->cb = cb;
		adv->options = param->options;
		legacy_adv_pending[dev_id].adv = adv;
		legacy_adv_pending[dev_id].param = *param;
		*out_adv = adv;
		if (diag) {
			syslog(LOG_INFO,
			       "ov_ble_adv_diag: zblue adv: create returned status=0\n");
		}
		return 0;
	}

	syslog(LOG_INFO,
	       "ov_ble_adv_diag: zblue adv: selected extended hci\n");

	adv = adv_new(hdev);
	if (!adv) {
		if (diag) {
			syslog(LOG_INFO, "ov_ble_adv_diag: zblue adv: create returned status=%d\n", -ENOMEM);
		}
		return -ENOMEM;
	}

	adv->hdev = hdev;
	adv->id = param->id;
	adv->cb = cb;

	err = le_ext_adv_param_set(adv, param, false);
	if (err) {
		if (diag) {
			syslog(LOG_INFO, "ov_ble_adv_diag: zblue adv: create returned status=%d\n", err);
		}
		adv_delete(adv);
		return err;
	}

	*out_adv = adv;
	if (diag) {
		syslog(LOG_INFO, "ov_ble_adv_diag: zblue adv: create returned status=0\n");
	}
	return 0;
}

int bt_le_ext_adv_update_param(struct bt_le_ext_adv *adv,
			       const struct bt_le_adv_param *param)
{
	if (!valid_adv_ext_param(adv->hdev, param)) {
		return -EINVAL;
	}

	if (IS_ENABLED(CONFIG_BT_PER_ADV) &&
	    atomic_test_bit(adv->flags, BT_PER_ADV_PARAMS_SET)) {
		/* If params for per adv has been set, do not allow setting
		 * connectable, scanable or use legacy adv
		 */
		if (param->options & _BT_LE_ADV_OPT_CONNECTABLE ||
		    param->options & BT_LE_ADV_OPT_SCANNABLE ||
		    !(param->options & BT_LE_ADV_OPT_EXT_ADV) ||
		    param->options & BT_LE_ADV_OPT_ANONYMOUS) {
			return -EINVAL;
		}
	}

	if (atomic_test_bit(adv->flags, BT_ADV_ENABLED)) {
		return -EINVAL;
	}

	if (param->id != adv->id) {
		atomic_clear_bit(adv->flags, BT_ADV_RPA_VALID);
	}

	return le_ext_adv_param_set(adv, param, false);
}

int bt_le_ext_adv_start(struct bt_le_ext_adv *adv,
			const struct bt_le_ext_adv_start_param *param)
{
	struct bt_conn *conn = NULL;
	int err;

	if (bt_le_adv_uses_legacy_hci(adv)) {
		return 0;
	}

	if (atomic_test_bit(adv->flags, BT_ADV_ENABLED)) {
		return -EALREADY;
	}

	if (IS_ENABLED(CONFIG_BT_PERIPHERAL) &&
	    atomic_test_bit(adv->flags, BT_ADV_CONNECTABLE)) {
		err = le_adv_start_add_conn(adv, &conn);
		if (err) {
			return err;
		}
	}

	atomic_set_bit_to(adv->flags, BT_ADV_LIMITED, param &&
			  (param->timeout > 0 || param->num_events > 0));

	if (atomic_test_bit(adv->flags, BT_ADV_CONNECTABLE)) {
		if (IS_ENABLED(CONFIG_BT_PRIVACY) &&
		    !atomic_test_bit(adv->flags, BT_ADV_USE_IDENTITY)) {
			bt_id_set_adv_private_addr(adv);
		}
	} else {
		if (!atomic_test_bit(adv->flags, BT_ADV_USE_IDENTITY)) {
			bt_id_set_adv_private_addr(adv);
		}
	}

	if (get_adv_name_type(adv) != ADV_NAME_TYPE_NONE &&
	    !atomic_test_bit(adv->flags, BT_ADV_DATA_SET)) {
		/* Set the advertiser name */
		bt_le_ext_adv_set_data(adv, NULL, 0, NULL, 0);
	}

	err = bt_le_adv_set_enable_ext(adv, true, param);
	if (err) {
		LOG_ERR("Failed to start advertiser");
