static inline bool adv_is_directed(const struct bt_le_ext_adv *adv)
{
	/* The advertiser is assumed to be directed when the peer address has
	 * been set.
	 */
	return !bt_addr_le_eq(&adv->target_addr, BT_ADDR_LE_ANY);
}

static int le_adv_start_add_conn(const struct bt_le_ext_adv *adv,
				 struct bt_conn **out_conn)
{
	struct bt_conn *conn;
	struct bt_dev *hdev = adv->hdev;

	hdev->adv_conn_id = adv->id;

	if (!adv_is_directed(adv)) {
		/* Undirected advertising */
		conn = bt_conn_add_le(hdev, adv->id, BT_ADDR_LE_NONE);
		if (!conn) {
			return -ENOMEM;
		}

		bt_conn_set_state(conn, BT_CONN_ADV_CONNECTABLE);
		*out_conn = conn;
		return 0;
	}

	if (bt_conn_exists_le(hdev, adv->id, &adv->target_addr)) {
		return -EINVAL;
	}

	conn = bt_conn_add_le(hdev, adv->id, &adv->target_addr);
	if (!conn) {
		return -ENOMEM;
	}

	bt_conn_set_state(conn, BT_CONN_ADV_DIR_CONNECTABLE);
	*out_conn = conn;
	return 0;
}

static void le_adv_stop_free_conn(const struct bt_le_ext_adv *adv, uint8_t status)
{
	struct bt_conn *conn;

	if (!adv_is_directed(adv)) {
		conn = bt_conn_lookup_state_le(adv->hdev, adv->id, BT_ADDR_LE_NONE,
					       BT_CONN_ADV_CONNECTABLE);
	} else {
		conn = bt_conn_lookup_state_le(adv->hdev, adv->id, &adv->target_addr,
					       BT_CONN_ADV_DIR_CONNECTABLE);
	}

	if (conn) {
		conn->err = status;
		bt_conn_set_state(conn, BT_CONN_DISCONNECTED);
		bt_conn_unref(conn);
	}
}

int bt_le_adv_start_legacy(struct bt_le_ext_adv *adv,
			   const struct bt_le_adv_param *param,
			   const struct bt_data *ad, size_t ad_len,
			   const struct bt_data *sd, size_t sd_len)
{
	struct bt_hci_cp_le_set_adv_param set_param;
	struct bt_conn *conn = NULL;
	struct net_buf *buf;
	bool dir_adv = (param->peer != NULL), scannable = false;
	enum adv_name_type name_type;

	int err;

	if (!atomic_test_bit(adv->hdev->flags, BT_DEV_READY)) {
		return -EAGAIN;
	}

	if (!valid_adv_param(adv->hdev, param)) {
		return -EINVAL;
	}

	if (!bt_id_adv_random_addr_check(adv->hdev, param)) {
		return -EINVAL;
	}

	if (atomic_test_bit(adv->flags, BT_ADV_ENABLED)) {
		return -EALREADY;
	}

	(void)memset(&set_param, 0, sizeof(set_param));

	set_param.min_interval = sys_cpu_to_le16(param->interval_min);
	set_param.max_interval = sys_cpu_to_le16(param->interval_max);
	set_param.channel_map  = get_adv_channel_map(param->options);
	set_param.filter_policy = get_filter_policy(param->options);

	atomic_clear_bit(adv->hdev->flags, BT_DEV_RPA_VALID);

	adv->id = param->id;
	adv->hdev->adv_conn_id = adv->id;

	err = bt_id_set_adv_own_addr(adv, param->options, dir_adv,
				     &set_param.own_addr_type);
	if (err) {
		return err;
	}

	if (dir_adv) {
		bt_addr_le_copy(&adv->target_addr, param->peer);
	} else {
		bt_addr_le_copy(&adv->target_addr, BT_ADDR_LE_ANY);
	}

	name_type = get_adv_name_type_param(param);

	if (param->options & _BT_LE_ADV_OPT_CONNECTABLE) {
		if (dir_adv) {
			if (param->options & BT_LE_ADV_OPT_DIR_MODE_LOW_DUTY) {
				set_param.type = BT_HCI_ADV_DIRECT_IND_LOW_DUTY;
			} else {
				set_param.type = BT_HCI_ADV_DIRECT_IND;
			}

			bt_addr_le_copy(&set_param.direct_addr, param->peer);
		} else {
			scannable = true;
			set_param.type = BT_HCI_ADV_IND;
		}
	} else if ((param->options & BT_LE_ADV_OPT_SCANNABLE) || sd ||
		   (name_type == ADV_NAME_TYPE_SD)) {
		scannable = true;
		set_param.type = BT_HCI_ADV_SCAN_IND;
	} else {
		set_param.type = BT_HCI_ADV_NONCONN_IND;
	}

	buf = bt_hci_cmd_create(BT_HCI_OP_LE_SET_ADV_PARAM, sizeof(set_param));
	if (!buf) {
		return -ENOBUFS;
  .on_advertising_stopped = on_advertising_stopped,
};

static int start_advertising(void)
{
  ble_adv_params_t params;

  if (g_advertiser != NULL)
    {
      return 0;
    }

  memset(&params, 0, sizeof(params));
  params.adv_type = BT_LE_LEGACY_ADV_IND;
  params.interval = 320;
  params.duration = 0;
  params.channel_map = BT_LE_ADV_CHANNEL_DEFAULT;
  params.filter_policy = BT_LE_ADV_FILTER_WHITE_LIST_FOR_NONE;

  if (g_adv_data == NULL || g_scan_rsp_data == NULL)
    {
      g_adv_data = advertiser_data_new();
      g_scan_rsp_data = advertiser_data_new();
      if (g_adv_data == NULL || g_scan_rsp_data == NULL)
        {
          printf("openvela_ble_probe: advertiser_data_new failed\n");
          return -1;
        }

      advertiser_data_set_flags(g_adv_data,
                                BT_AD_FLAG_GENERAL_DISCOVERABLE |
                                BT_AD_FLAG_BREDR_NOT_SUPPORT);
      advertiser_data_set_name(g_scan_rsp_data, "ov_ble_probe");

      g_adv_payload = advertiser_data_build(g_adv_data,
                                            &g_adv_payload_len);
      g_scan_rsp_payload = advertiser_data_build(g_scan_rsp_data,
                                                 &g_scan_rsp_payload_len);
      if (g_adv_payload == NULL || g_scan_rsp_payload == NULL)
        {
          printf("openvela_ble_probe: advertiser_data_build failed\n");
          return -1;
        }
    }

  syslog(LOG_INFO, "ov_ble_adv_diag: probe adv: request begin\n");
  g_advertiser = bt_le_start_advertising(g_instance, &params,
                                         g_adv_payload, g_adv_payload_len,
                                         g_scan_rsp_payload,
                                         g_scan_rsp_payload_len,
                                         &g_advertiser_callbacks);
  syslog(LOG_INFO, "ov_ble_adv_diag: probe adv: request returned status=%d\n",
         g_advertiser != NULL ? 0 : -1);
  if (g_advertiser == NULL)
    {
      printf("openvela_ble_probe: bt_le_start_advertising failed\n");
      return -1;
    }

  printf("openvela_ble_probe: advertising as ov_ble_probe\n");
  return 0;
}

