#define BT_LE_ADV_INTERVAL_MAX                  0x4000
#define BT_LE_ADV_INTERVAL_DEFAULT              0x0800

#define BT_LE_ADV_CHAN_MAP_CHAN_37              0x01
#define BT_LE_ADV_CHAN_MAP_CHAN_38              0x02
#define BT_LE_ADV_CHAN_MAP_CHAN_39              0x04
#define BT_LE_ADV_CHAN_MAP_ALL                  0x07

#define BT_LE_ADV_FP_NO_FILTER                  0x00
#define BT_LE_ADV_FP_FILTER_SCAN_REQ            0x01
#define BT_LE_ADV_FP_FILTER_CONN_IND            0x02
#define BT_LE_ADV_FP_FILTER_BOTH                0x03

#define BT_HCI_OP_LE_SET_ADV_PARAM              BT_OP(BT_OGF_LE, 0x0006) /* 0x2006 */
struct bt_hci_cp_le_set_adv_param {
	uint16_t     min_interval;
	uint16_t     max_interval;
	uint8_t      type;
	uint8_t      own_addr_type;
	bt_addr_le_t direct_addr;
	uint8_t      channel_map;
	uint8_t      filter_policy;
} __packed;

#define BT_HCI_OP_LE_READ_ADV_CHAN_TX_POWER     BT_OP(BT_OGF_LE, 0x0007) /* 0x2007 */
struct bt_hci_rp_le_read_chan_tx_power {
	uint8_t status;
	int8_t  tx_power_level;
} __packed;

#define BT_HCI_OP_LE_SET_ADV_DATA               BT_OP(BT_OGF_LE, 0x0008) /* 0x2008 */
struct bt_hci_cp_le_set_adv_data {
	uint8_t  len;
	uint8_t  data[31];
} __packed;


static void le_adv_stop_free_conn(const struct bt_le_ext_adv *adv, uint8_t status)
{
	struct bt_conn *conn;

	if (!adv_is_directed(adv)) {
		conn = bt_conn_lookup_state_le(adv->hdev, adv->id, BT_ADDR_LE_NONE,
					       BT_CONN_ADV_CONNECTABLE);
	} else {
		conn = bt_conn_lookup_state_le(adv->hdev, adv->id, &adv->target_addr,
					       BT_CONN_ADV_DIR_CONNECTABLE);
	}

	if (conn) {
		conn->err = status;
		bt_conn_set_state(conn, BT_CONN_DISCONNECTED);
		bt_conn_unref(conn);
	}
}

int bt_le_adv_start_legacy(struct bt_le_ext_adv *adv,
			   const struct bt_le_adv_param *param,
			   const struct bt_data *ad, size_t ad_len,
			   const struct bt_data *sd, size_t sd_len)
{
	struct bt_hci_cp_le_set_adv_param set_param;
	struct bt_conn *conn = NULL;
	struct net_buf *buf;
	bool dir_adv = (param->peer != NULL), scannable = false;
	enum adv_name_type name_type;

	int err;

	if (!atomic_test_bit(adv->hdev->flags, BT_DEV_READY)) {
		return -EAGAIN;
	}

	if (!valid_adv_param(adv->hdev, param)) {
		return -EINVAL;
	}

	if (!bt_id_adv_random_addr_check(adv->hdev, param)) {
		return -EINVAL;
	}

	if (atomic_test_bit(adv->flags, BT_ADV_ENABLED)) {
		return -EALREADY;
	}

	(void)memset(&set_param, 0, sizeof(set_param));

	set_param.min_interval = sys_cpu_to_le16(param->interval_min);
	set_param.max_interval = sys_cpu_to_le16(param->interval_max);
	set_param.channel_map  = get_adv_channel_map(param->options);
	set_param.filter_policy = get_filter_policy(param->options);

	atomic_clear_bit(adv->hdev->flags, BT_DEV_RPA_VALID);

	adv->id = param->id;
	adv->hdev->adv_conn_id = adv->id;

	err = bt_id_set_adv_own_addr(adv, param->options, dir_adv,
				     &set_param.own_addr_type);
	if (err) {
		return err;
	}

	if (dir_adv) {
		bt_addr_le_copy(&adv->target_addr, param->peer);
	} else {
		bt_addr_le_copy(&adv->target_addr, BT_ADDR_LE_ANY);
	}

	name_type = get_adv_name_type_param(param);

	if (param->options & _BT_LE_ADV_OPT_CONNECTABLE) {
		if (dir_adv) {
			if (param->options & BT_LE_ADV_OPT_DIR_MODE_LOW_DUTY) {
				set_param.type = BT_HCI_ADV_DIRECT_IND_LOW_DUTY;
			} else {
				set_param.type = BT_HCI_ADV_DIRECT_IND;
			}

			bt_addr_le_copy(&set_param.direct_addr, param->peer);
		} else {
			scannable = true;
			set_param.type = BT_HCI_ADV_IND;
		}
	} else if ((param->options & BT_LE_ADV_OPT_SCANNABLE) || sd ||
		   (name_type == ADV_NAME_TYPE_SD)) {
		scannable = true;
		set_param.type = BT_HCI_ADV_SCAN_IND;
	} else {
		set_param.type = BT_HCI_ADV_NONCONN_IND;
	}

	buf = bt_hci_cmd_create(BT_HCI_OP_LE_SET_ADV_PARAM, sizeof(set_param));
	if (!buf) {
		return -ENOBUFS;
	}

	net_buf_add_mem(buf, &set_param, sizeof(set_param));

	err = bt_hci_cmd_send_sync(adv->hdev, BT_HCI_OP_LE_SET_ADV_PARAM, buf, NULL);
	if (err) {
		return err;
	}

	if (!dir_adv) {
		err = le_adv_update(adv, ad, ad_len, sd, sd_len, false,
				    scannable, name_type);
		if (err) {
			return err;
		}
	}

	if (IS_ENABLED(CONFIG_BT_PERIPHERAL) &&
	    (param->options & _BT_LE_ADV_OPT_CONNECTABLE)) {
		err = le_adv_start_add_conn(adv, &conn);
		if (err) {
			if (err == -ENOMEM && !dir_adv &&
			    !(param->options & _BT_LE_ADV_OPT_ONE_TIME)) {
				goto set_adv_state;
			}

			return err;
{
	struct bt_le_ext_adv *adv;
	int err;
	struct bt_dev *hdev;
	bool diag = ov_ble_adv_diag_param(param);

	if (diag) {
		syslog(LOG_INFO, "ov_ble_adv_diag: zblue adv: create begin\n");
	}

	hdev = bt_dev_get(dev_id);
	if (!hdev) {
		if (diag) {
			syslog(LOG_INFO, "ov_ble_adv_diag: zblue adv: create returned status=%d\n", -ENODEV);
		}
		return -ENODEV;
	}

	if (!atomic_test_bit(hdev->flags, BT_DEV_READY)) {
		if (diag) {
			syslog(LOG_INFO, "ov_ble_adv_diag: zblue adv: create returned status=%d\n", -EAGAIN);
		}
		return -EAGAIN;
	}

	if (!valid_adv_ext_param(hdev, param)) {
		if (diag) {
			syslog(LOG_INFO, "ov_ble_adv_diag: zblue adv: create returned status=%d\n", -EINVAL);
		}
		return -EINVAL;
	}

	if (ZBLUE_FORCE_LEGACY_HCI_FOR_LEGACY_ADV &&
	    !(param->options & BT_LE_ADV_OPT_EXT_ADV) &&
	    (param->options & _BT_LE_ADV_OPT_CONNECTABLE) &&
	    (param->options & BT_LE_ADV_OPT_SCANNABLE)) {
		err = adv_create_legacy(hdev);
		if (err) {
			return err;
		}

		adv = bt_le_adv_lookup_legacy(hdev);
		adv->id = param->id;
		adv->cb = cb;
		adv->options = param->options;
		legacy_adv_pending[dev_id].adv = adv;
		legacy_adv_pending[dev_id].param = *param;
		*out_adv = adv;
		if (diag) {
			syslog(LOG_INFO,
			       "ov_ble_adv_diag: zblue adv: create returned status=0\n");
		}
		return 0;
	}

	syslog(LOG_INFO,
	       "ov_ble_adv_diag: zblue adv: selected extended hci\n");

	adv = adv_new(hdev);
	if (!adv) {
		if (diag) {
			syslog(LOG_INFO, "ov_ble_adv_diag: zblue adv: create returned status=%d\n", -ENOMEM);
		}
		return -ENOMEM;
	}

	}

	if (atomic_test_and_clear_bit(adv->flags, BT_ADV_LIMITED)) {
		bt_id_adv_limited_stopped(adv);

#if defined(CONFIG_BT_SMP)
		bt_id_pending_keys_update(adv->hdev);
#endif
	}

	if (IS_ENABLED(CONFIG_BT_PERIPHERAL) &&
	    atomic_test_bit(adv->flags, BT_ADV_CONNECTABLE)) {
		le_adv_stop_free_conn(adv, 0);
	}

	if (bt_le_adv_uses_legacy_hci(adv)) {
		return bt_le_adv_set_enable_legacy(adv, false);
	}

	return bt_le_adv_set_enable_ext(adv, false, NULL);
}

int bt_le_ext_adv_set_data(struct bt_le_ext_adv *adv,
			   const struct bt_data *ad, size_t ad_len,
			   const struct bt_data *sd, size_t sd_len)
{
	bool ext_adv, scannable;
	uint8_t dev_id = adv->hdev->dev_id;
	int err;

	if (dev_id < ARRAY_SIZE(legacy_adv_pending) &&
	    legacy_adv_pending[dev_id].adv == adv) {
		struct bt_le_adv_param *param =
			&legacy_adv_pending[dev_id].param;

		legacy_adv_pending[dev_id].adv = NULL;
		if (legacy_adv_data_fits(adv->hdev, param,
					 ad, ad_len, sd, sd_len)) {
			adv->options = param->options |
				       ZBLUE_ADV_OPT_INTERNAL_LEGACY_HCI;
			syslog(LOG_INFO,
			       "ov_ble_adv_diag: zblue adv: selected legacy hci\n");
			err = bt_le_adv_start_legacy(adv, param,
						     ad, ad_len, sd, sd_len);
			if (!err) {
				/* The bt_le_ext_adv_* facade is one-shot on connect. */
				atomic_clear_bit(adv->flags, BT_ADV_PERSIST);
			}

			return err;
		}

		syslog(LOG_INFO,
		       "ov_ble_adv_diag: zblue adv: selected extended hci\n");
		err = le_ext_adv_param_set(adv, param, false);
		if (err) {
			return err;
		}
	}

