   409	int bt_hci_cmd_send(struct bt_dev *hdev, uint16_t opcode, struct net_buf *buf)
   410	{
   411		if (!buf) {
   412			buf = bt_hci_cmd_create(opcode, 0);
   413			if (!buf) {
   414				return -ENOBUFS;
   415			}
   416		}
   417	
   418		LOG_DBG("opcode 0x%04x %s len %u", opcode, bt_hci_opcode_to_str(opcode), buf->len);
   419	
   420		/* Host Number of Completed Packets can ignore the ncmd value
   421		 * and does not generate any cmd complete/status events.
   422		 */
   423		if (opcode == BT_HCI_OP_HOST_NUM_COMPLETED_PACKETS) {
   424			int err;
   425	
   426			err = bt_send(hdev, buf);
   427			if (err) {
   428				LOG_ERR("Unable to send to driver (err %d)", err);
   429				net_buf_unref(buf);
   430			}
   431	
   432			return err;
   433		}
   434	
   435		k_fifo_put(&hdev->cmd_tx_queue, buf);
   436		bt_tx_irq_raise(hdev);
   437	
   438		return 0;
   439	}
