   378	struct net_buf *bt_hci_cmd_create(uint16_t opcode, uint8_t param_len)
   379	{
   380		struct bt_hci_cmd_hdr *hdr;
   381		struct net_buf *buf;
   382	
   383		LOG_DBG("opcode 0x%04x %s param_len %u", opcode, bt_hci_opcode_to_str(opcode), param_len);
   384	
   385		/* net_buf_alloc(K_FOREVER) can fail when run from the syswq */
   386		buf = net_buf_alloc(&hci_cmd_pool, K_FOREVER);
   387		if (!buf) {
   388			LOG_DBG("Unable to allocate a command buffer");
   389			return NULL;
   390		}
   391	
   392		LOG_DBG("buf %p", buf);
   393	
   394		net_buf_reserve(buf, BT_BUF_RESERVE);
   395	
   396		bt_buf_set_type(buf, BT_BUF_CMD);
   397	
   398		cmd(buf)->opcode = opcode;
   399		cmd(buf)->sync = NULL;
   400		cmd(buf)->state = NULL;
   401	
   402		hdr = net_buf_add(buf, sizeof(*hdr));
   403		hdr->opcode = sys_cpu_to_le16(opcode);
   404		hdr->param_len = param_len;
   405	
   406		return buf;
