  2551	static void hci_cmd_done(struct bt_dev *hdev, uint16_t opcode,
  2552				 uint8_t status, struct net_buf *evt_buf)
  2553	{
  2554		/* Original command buffer. */
  2555		struct net_buf *buf = NULL;
  2556	
  2557		LOG_DBG("opcode 0x%04x %s, status 0x%02x %s buf %p", opcode,
  2558			bt_hci_opcode_to_str(opcode),
  2559			status, bt_hci_err_to_str(status), evt_buf);
  2560	
  2561		/* Unsolicited cmd complete. This does not complete a command.
  2562		 * The controller can send these for effect of the `ncmd` field.
  2563		 */
  2564		if (opcode == 0) {
  2565			goto exit;
  2566		}
  2567	
  2568		/* Take the original command buffer reference. */
  2569		buf = (struct net_buf *)atomic_ptr_clear((atomic_ptr_t *)&hdev->sent_cmd);
  2570	
  2571		if (!buf) {
  2572			LOG_ERR("No command sent for cmd complete 0x%04x", opcode);
  2573			goto exit;
  2574		}
  2575	
  2576		if (cmd(buf)->opcode != opcode) {
  2577			LOG_ERR("OpCode 0x%04x %s completed instead of expected 0x%04x %s", opcode,
  2578				bt_hci_opcode_to_str(opcode), cmd(buf)->opcode, bt_hci_opcode_to_str(cmd(buf)->opcode));
  2579			buf = atomic_ptr_set((atomic_ptr_t *)&hdev->sent_cmd, buf);
  2580			__ASSERT_NO_MSG(!buf);
  2581			goto exit;
  2582		}
  2583	
  2584		/* Response data is to be delivered in the original command
  2585		 * buffer.
  2586		 */
  2587		if (evt_buf != buf) {
  2588			net_buf_reset(buf);
  2589			bt_buf_set_type(buf, BT_BUF_EVT);
  2590			net_buf_reserve(buf, BT_BUF_RESERVE);
  2591			net_buf_add_mem(buf, evt_buf->data, evt_buf->len);
  2592		}
  2593	
  2594		if (cmd(buf)->state && !status) {
  2595			struct bt_hci_cmd_state_set *update = cmd(buf)->state;
  2596	
  2597			atomic_set_bit_to(update->target, update->bit, update->val);
  2598		}
