423	static void sf32lb52_bt_rx_worker(FAR void *arg)
424	{
425	  struct sf32lb52_bt_env_s *env = arg;
426	
427	  for (;;)
428	    {
429	      irqstate_t flags;
430	      int empty_retries = 0;
431	
432	      for (;;)
433	        {
434	          size_t size;
435	          size_t read_len;
436	          int ret;
437	          struct circular_buf *rx_ring;
438	          uint32_t wr_ptr;
439	
440	          flags = enter_critical_section();
441	
442	          if (!env->queue_open || env->ipc_port == IPC_QUEUE_INVALID_HANDLE)
443	            {
444	              env->rx_work_pending = false;
445	              env->rx_worker_running = false;
446	              leave_critical_section(flags);
447	              return;
448	            }
449	
450	          leave_critical_section(flags);
451	
452	          up_invalidate_dcache((uintptr_t)SF32LB52_BT_RX_BUF_ADDR,
453	                               (uintptr_t)SF32LB52_BT_RX_BUF_ADDR +
454	                               SF32LB52_BT_RX_BUF_SIZE);
455	
456	          flags = enter_critical_section();
457	
458	          if (!env->queue_open || env->ipc_port == IPC_QUEUE_INVALID_HANDLE)
459	            {
460	              env->rx_work_pending = false;
461	              env->rx_worker_running = false;
462	              leave_critical_section(flags);
463	              return;
464	            }
465	
466	          rx_ring = (struct circular_buf *)SF32LB52_BT_RX_BUF_ADDR;
467	          wr_ptr = rx_ring->write_idx_mirror;
468	          size = sf32lb52_bt_ring_data_len(env->rx_read_idx_mirror,
469	                                          wr_ptr,
470	                                          rx_ring->buffer_size);
471	          if (size == 0)
472	            {
473	              uint32_t rd_ptr = rx_ring->read_idx_mirror;
474	              uint32_t local_rd = env->rx_read_idx_mirror;
475	
476	              leave_critical_section(flags);
477	
478	              if (empty_retries++ < 20)
479	                {
480	                  usleep(1000);
481	                  continue;
482	                }
483	
484	          #if SF32LB52_BT_TRACE
485	              syslog(LOG_INFO,
486	                "sf32lb52 bt rx empty: local=%08lx rd=%08lx wr=%08lx\n",
487	                (unsigned long)local_rd,
488	                (unsigned long)rd_ptr,
489	                (unsigned long)wr_ptr);
490	          #endif
491	              break;
492	            }
493	
494	          empty_retries = 0;
495	
496	          if (size > sizeof(env->data_buf))
497	            {
498	              size = sizeof(env->data_buf);
499	            }
500	
580	
581	  flags = enter_critical_section();
582	  env->rx_work_pending = true;
583	  work_ready = work_available(&env->rx_work);
584	  queue_work = !env->rx_worker_running && work_ready;
585	  if (queue_work)
586	    {
587	      env->rx_worker_running = true;
588	      env->rx_exit_window_reported = false;
589	    }
590	  else if (!env->rx_worker_running && !work_ready &&
591	           !env->rx_exit_window_reported)
592	    {
593	      env->rx_exit_window_reported = true;
594	      report_exit_window = true;
595	    }
596	  leave_critical_section(flags);
597	
598	  if (report_exit_window)
599	    {
600	      syslog(LOG_WARNING, "sf32lb52 bt RX worker exit window hit\n");
601	    }
602	
603	#if SF32LB52_BT_TRACE
604	  {
605	    struct circular_buf *rx_ring =
606	        (struct circular_buf *)SF32LB52_BT_RX_BUF_ADDR;
607	
608	    up_invalidate_dcache((uintptr_t)SF32LB52_BT_RX_BUF_ADDR,
609	                         (uintptr_t)SF32LB52_BT_RX_BUF_ADDR +
610	                         sizeof(*rx_ring));
611	
612	    syslog(LOG_INFO,
613	           "sf32lb52 rx_ind: size=%lu local=%08lx rd=%08lx wr=%08lx\n",
614	           (unsigned long)size,
615	           (unsigned long)env->rx_read_idx_mirror,
616	           (unsigned long)rx_ring->read_idx_mirror,
617	           (unsigned long)rx_ring->write_idx_mirror);
618	  }
619	#endif
620	
621	  if (queue_work)
622	    {
623	      int ret;
624	
625	      ret = work_queue(HPWORK, &env->rx_work, sf32lb52_bt_rx_worker,
626	                       env, 0);
627	      if (ret < 0)
628	        {
629	          flags = enter_critical_section();
630	          env->rx_worker_running = false;
631	          leave_critical_section(flags);
632	
633	          syslog(LOG_ERR, "sf32lb52 bt queue rx work failed: %d\n", ret);
634	          return ret;
635	        }
636	    }
637	
638	  return OK;
639	}
