350	  switch (data[0])
351	    {
352	      case H4_EVT:
353	        sf32lb52_bt_log_adv_diag_event(data, len);
354	        #if SF32LB52_BT_NORMALIZE_RESET_STATUS
355	          sf32lb52_bt_normalize_event(data, len);
356	        #endif
357	        type = BT_EVT;
358	        break;
359	
360	      case H4_ACL:
361	        type = BT_ACL_IN;
362	        break;
363	
364	      case H4_ISO:
365	        type = BT_ISO_IN;
366	        break;
367	
