903	int sf32lb52_host_send_packet(const uint8_t *data, uint16_t len)
904	{
905	  struct circular_buf *tx_ring =
906	      (struct circular_buf *)SF32LB52_BT_TX_BUF_ADDR;
907	  uint32_t start_time;
908	  uint32_t tick_count;
909	  size_t written;
910	  size_t remaining;
911	  size_t offset;
912	  size_t chunk;
913	  size_t chunks;
914	  uint32_t wr_ptr;
915	  int ret;
916	
917	  if (data == NULL || len == 0)
918	    {
919	      return -EINVAL;
920	    }
921	
922	  if (g_sf32lb52_bt_status != SF32LB52_BT_STATUS_ENABLED ||
923	      !g_sf32lb52_bt_env.queue_open)
924	    {
925	      return -ENODEV;
926	    }
927	
928	  offset = 0;
929	  remaining = len;
930	  start_time = HAL_GetTick();
931	  tick_count = 0;
932	  chunks = 0;
933	  wr_ptr = 0;
934	
935	  ret = sf32lb52_bt_wait_tx_idle(tx_ring);
936	  if (ret < 0)
937	    {
938	      return ret;
939	    }
940	
941	  while (remaining > 0)
942	    {
943	      irqstate_t flags;
944	
945	      chunk = sf32lb52_bt_tx_chunk_len(data, len, offset);
946	
947	      up_invalidate_dcache((uintptr_t)SF32LB52_BT_TX_BUF_ADDR,
948	                           (uintptr_t)SF32LB52_BT_TX_BUF_ADDR +
949	                           sizeof(*tx_ring));
950	
951	      flags = enter_critical_section();
952	      written = sf32lb52_bt_ring_write(tx_ring, data + offset, chunk);
953	      leave_critical_section(flags);
954	
955	      if (written == 0)
956	        {
957	          if (HAL_GetTick() != start_time)
958	            {
959	              tick_count++;
960	              start_time = HAL_GetTick();
961	            }
962	
963	          if (tick_count >= 10)
964	            {
965	              syslog(LOG_ERR,
966	                     "sf32lb52 bt tx timeout: remaining=%lu\n",
967	                     (unsigned long)remaining);
968	              return -ETIMEDOUT;
969	            }
970	
971	          continue;
972	        }
973	
974	      offset += written;
975	      remaining -= written;
976	
977	      __DSB();
978	      wr_ptr = tx_ring->write_idx_mirror;
979	      sf32lb52_bt_trigger_tx();
980	      chunks++;
981	    }
982	
983	#if SF32LB52_BT_TRACE
984	  syslog(LOG_INFO,
985	         "sf32lb52 bt tx publish: total=%u chunks=%lu wr=%08lx first=%02x\n",
986	         len,
987	         (unsigned long)chunks,
988	         (unsigned long)wr_ptr,
989	         data[0]);
990

