 90	{
 91	    int ret, nwritten = 0;
 92	
 93	    while (nwritten != count) {
 94	        ret = write(fd, buf + nwritten, count - nwritten);
 95	        if (ret < 0) {
 96	            if (errno == EAGAIN) {
 97	                usleep(1000);
 98	                continue;
 99	            } else
100	                return ret;
101	        }
102	
103	        nwritten += ret;
104	    }
105	
106	    return nwritten;
