637	      case BT_ISO_OUT:
638	        *hdr = H4_ISO;
639	        break;
640	      default:
641	        return -EINVAL;
642	    }
643	
644	  if (type == BT_CMD && len >= sizeof(struct bt_hci_cmd_hdr_s))
645	    {
646	      opcode = sf32lb52_bt_get_le16(data);
647	
648	      if (sf32lb52_bt_is_adv_diag_opcode(opcode) &&
649	          len >= sizeof(struct bt_hci_cmd_hdr_s) + ((uint8_t *)data)[2])
650	        {
651	          syslog(LOG_INFO,
652	                 "ov_ble_adv_diag: h4: command tx opcode=0x%04x\n",
653	                 opcode);
654	        }
655	
656	  #if SF32LB52_BT_TRACE
657	    syslog(LOG_INFO,
658	            "sf32lb52 bth4 hci tx: opcode=0x%04x len=%lu\n",
659	            opcode, (unsigned long)len);
660	    #endif
661	
662	  #if SF32LB52_BT_COMPAT_BR_INIT
663	    if (opcode == BT_HCI_OP_WRITE_LOCAL_NAME)
664	      {
665	        syslog(LOG_INFO,
666	               "sf32lb52 bth4 compat: synth BR init opcode=0x%04x\n",
667	               opcode);
668	        ret = sf32lb52_bt_synth_status_complete(priv, opcode);
669	        return ret < 0 ? ret : len;
670	      }
671	    #endif
672	
673	  #if SF32LB52_BT_EMULATE_HCI
674	    if (sf32lb52_bt_emulate_cmd(priv, opcode, &ret))
675	    {
676	      return ret < 0 ? ret : len;
677	    }
678	    #endif
679	
680	  ret = sf32lb52_bt_ensure_controller_enabled(opcode);
681	      if (ret < 0)
682	        {
683	          return ret;
684	        }
685	    }
686	  else
687	    {
688	      ret = sf32lb52_bt_ensure_controller_enabled(0);
689	      if (ret < 0)
690	        {
691	          return ret;
692	        }
693	    }
694	
695	  priv->drop_rx_until_tx = false;
696	
697	  if (SF32LB52_BT_TRACE_ACL && type == BT_ACL_OUT)
698	    {
699	      syslog(LOG_INFO,
700	             "sf32lb52 bth4 tx: type=%u len=%lu h4=%02x acl=%02x %02x %02x %02x\n",
701	             (unsigned int)type,
702	             (unsigned long)(len + drv->head_reserve),
703	             hdr[0],
704	             len >= 1 ? hdr[1] : 0,
705	             len >= 2 ? hdr[2] : 0,
706	             len >= 3 ? hdr[3] : 0,
707	             len >= 4 ? hdr[4] : 0);
708	    }
709	
710	  ret = sf32lb52_host_send_packet(hdr, len + drv->head_reserve);
711	  if (ret < 0)
712	    {
713	      return ret;
714	    }
715	
716	  return len;
717	}
