   243	static int handle_event_common(struct bt_dev *hdev, uint8_t event, struct net_buf *buf,
   244				       const struct event_handler *handlers, size_t num_handlers)
   245	{
   246		size_t i;
   247	
   248		for (i = 0; i < num_handlers; i++) {
   249			const struct event_handler *handler = &handlers[i];
   250	
   251			if (handler->event != event) {
   252				continue;
   253			}
   254	
   255			if (buf->len < handler->min_len) {
   256				LOG_ERR("Too small (%u bytes) event 0x%02x", buf->len, event);
   257				return -EINVAL;
   258			}
   259	
   260			handler->handler(hdev, buf);
   261			return 0;
   262		}
   263	
   264		return -EOPNOTSUPP;
   265	}
   266	
   267	static void handle_event(struct bt_dev *hdev, uint8_t event, struct net_buf *buf,
   268				 const struct event_handler *handlers, size_t num_handlers)
   269	{
   270		int err;
   271	
   272		err = handle_event_common(hdev, event, buf, handlers, num_handlers);
   273		if (err == -EOPNOTSUPP) {
   274			LOG_WRN("Unhandled event 0x%02x len %u: %s", event, buf->len,
   275				bt_hex(buf->data, buf->len));
   276		}
   277	
   278		/* Other possible errors are handled by handle_event_common function */
   279	}
