   196	        if (buf_len < header_len + BT_HCI_ISO_HDR_SIZE) {
   197	            return 0;
   198	        }
   199	
   200	        /* ISO_Data_Load_Length parameter */
   201	        payload_len = bt_iso_hdr_len(sys_le16_to_cpu(iso->len));
   202	        header_len += BT_HCI_ISO_HDR_SIZE;
