   238	static uint32_t sf32lb52_bt_ring_advance(uint32_t ptr, size_t len,
   239	                                         uint32_t buffer_size)
   240	{
   241	  uint32_t idx = CB_GET_PTR_IDX(ptr);
   242	  uint32_t mirror = CB_GET_PTR_MIRROR(ptr);
   243	
   244	  idx += len;
   245	  if (idx >= buffer_size)
   246	    {
   247	      idx -= buffer_size;
   248	      mirror = ~mirror;
   249	    }
   250	
   251	  return CB_MAKE_PTR_IDX_MIRROR(idx, mirror);
   252	}
   253	
   254	static size_t sf32lb52_bt_ring_copy(uint8_t *dst,
   255	                                    const struct circular_buf *rx_ring,
   256	                                    uint32_t rd_ptr,
   257	                                    size_t len)
   258	{
   259	  const uint8_t *pool = (const uint8_t *)(rx_ring + 1);
   260	  uint32_t rd_idx = CB_GET_PTR_IDX(rd_ptr);
   261	  size_t tail;
   262	
   263	  if (len == 0)
   264	    {
   265	      return 0;
   266	    }
   267	
   268	  tail = rx_ring->buffer_size - rd_idx;
   269	  if (tail >= len)
   270	    {
   271	      memcpy(dst, &pool[rd_idx], len);
   272	      return len;
   273	    }
   274	
   275	  memcpy(dst, &pool[rd_idx], tail);
   276	  memcpy(&dst[tail], pool, len - tail);
   277	  return len;
   278	}
   279	
   280	static size_t sf32lb52_bt_ring_write(struct circular_buf *tx_ring,
   281	                                     const uint8_t *src, size_t len)
   282	{
   283	  uint8_t *pool = (uint8_t *)(tx_ring + 1);
   284	  uint32_t wr_ptr = tx_ring->write_idx_mirror;
   285	  uint32_t wr_idx = CB_GET_PTR_IDX(wr_ptr);
   286	  size_t space;
   287	  size_t tail;
   288	
   289	  space = sf32lb52_bt_ring_space_len(tx_ring->read_idx_mirror,
   290	                                     wr_ptr,
   291	                                     tx_ring->buffer_size);
   292	  if (space == 0)
   293	    {
   294	      return 0;
   295	    }
   296	
   297	  if (len > space)
   298	    {
   299	      len = space;
   300	    }
   301	
   302	  tail = tx_ring->buffer_size - wr_idx;
   303	  if (tail >= len)
   304	    {
   305	      memcpy(&pool[wr_idx], src, len);
   306	      up_clean_dcache((uintptr_t)&pool[wr_idx],
   307	                      (uintptr_t)&pool[wr_idx] + len);
   308	    }
   309	  else
   310	    {
   311	      memcpy(&pool[wr_idx], src, tail);
   312	      memcpy(pool, &src[tail], len - tail);
   313	      up_clean_dcache((uintptr_t)&pool[wr_idx],
   314	                      (uintptr_t)&pool[wr_idx] + tail);
   315	      up_clean_dcache((uintptr_t)pool,
   316	                      (uintptr_t)pool + len - tail);
   317	    }
   318	
   319	  tx_ring->write_idx_mirror = sf32lb52_bt_ring_advance(wr_ptr, len,
   320	                                                       tx_ring->buffer_size);
   321	  up_clean_dcache((uintptr_t)tx_ring,
   322	                  (uintptr_t)tx_ring + sizeof(*tx_ring));
   323	  __DSB();
   324	
   325	  return len;
   326	}
