   328	static size_t sf32lb52_bt_tx_pending(struct circular_buf *tx_ring,
   329	                                     uint32_t *rd_ptr,
   330	                                     uint32_t *wr_ptr)
   331	{
   332	  uint32_t rd;
   333	  uint32_t wr;
   334	
   335	  up_invalidate_dcache((uintptr_t)SF32LB52_BT_TX_BUF_ADDR,
   336	                       (uintptr_t)SF32LB52_BT_TX_BUF_ADDR +
   337	                       sizeof(*tx_ring));
   338	
   339	  rd = tx_ring->read_idx_mirror;
   340	  wr = tx_ring->write_idx_mirror;
   341	
   342	  if (rd_ptr != NULL)
   343	    {
   344	      *rd_ptr = rd;
   345	    }
   346	
   347	  if (wr_ptr != NULL)
   348	    {
   349	      *wr_ptr = wr;
   350	    }
   351	
   352	  return sf32lb52_bt_ring_data_len(rd, wr, tx_ring->buffer_size);
   353	}
