   489	static void sf32lb52_bt_rx_worker(FAR void *arg)
   490	{
   491	  struct sf32lb52_bt_env_s *env = arg;
   492	
   493	  for (;;)
   494	    {
   495	      irqstate_t flags;
   496	      int empty_retries = 0;
   497	
   498	      for (;;)
   499	        {
   500	          size_t size;
   501	          size_t read_len;
   502	          int ret;
   503	          struct circular_buf *rx_ring;
   504	          uint32_t wr_ptr;
   505	          uint32_t rd_before;
   506	          bool adv_ipc_diag;
   507	
   508	          flags = enter_critical_section();
   509	
   510	          if (!env->queue_open || env->ipc_port == IPC_QUEUE_INVALID_HANDLE)
   511	            {
   512	              env->rx_work_pending = false;
   513	              env->rx_worker_running = false;
   514	              leave_critical_section(flags);
   515	              return;
   516	            }
   517	
   518	          leave_critical_section(flags);
   519	
   520	          up_invalidate_dcache((uintptr_t)SF32LB52_BT_RX_BUF_ADDR,
   521	                               (uintptr_t)SF32LB52_BT_RX_BUF_ADDR +
   522	                               SF32LB52_BT_RX_BUF_SIZE);
   523	
   524	          flags = enter_critical_section();
   525	
   526	          if (!env->queue_open || env->ipc_port == IPC_QUEUE_INVALID_HANDLE)
   527	            {
   528	              env->rx_work_pending = false;
   529	              env->rx_worker_running = false;
   530	              leave_critical_section(flags);
   531	              return;
   532	            }
   533	
   534	          rx_ring = (struct circular_buf *)SF32LB52_BT_RX_BUF_ADDR;
   535	          wr_ptr = rx_ring->write_idx_mirror;
   536	          rd_before = env->rx_read_idx_mirror;
   537	          size = sf32lb52_bt_ring_data_len(env->rx_read_idx_mirror,
   538	                                          wr_ptr,
   539	                                          rx_ring->buffer_size);
   540	          if (size == 0)
   541	            {
   542	              uint32_t rd_ptr = rx_ring->read_idx_mirror;
   543	              uint32_t local_rd = env->rx_read_idx_mirror;
   544	
   545	              leave_critical_section(flags);
   546	
   547	              if (empty_retries++ < 20)
   548	                {
   549	                  usleep(1000);
   550	                  continue;
   551	                }
   552	
   553	          #if SF32LB52_BT_TRACE
   554	              syslog(LOG_INFO,
   555	                "sf32lb52 bt rx empty: local=%08lx rd=%08lx wr=%08lx\n",
   556	                (unsigned long)local_rd,
   557	                (unsigned long)rd_ptr,
   558	                (unsigned long)wr_ptr);
   559	          #endif
   560	              break;
   561	            }
   562	
   563	          empty_retries = 0;
   564	
   565	          if (size > sizeof(env->data_buf))
   566	            {
   567	              size = sizeof(env->data_buf);
   568	            }
   569	
   570	          read_len = sf32lb52_bt_ring_copy(env->data_buf, rx_ring,
   571	                                           env->rx_read_idx_mirror, size);
   572	          if (read_len == 0)
   573	            {
   574	              leave_critical_section(flags);
   575	              break;
   576	            }
   577	
   578	          env->rx_read_idx_mirror = sf32lb52_bt_ring_advance(
   579	              env->rx_read_idx_mirror, read_len, rx_ring->buffer_size);
   580	          rx_ring->read_idx_mirror = env->rx_read_idx_mirror;
   581	          __DSB();
   582	
   583	          up_clean_dcache((uintptr_t)SF32LB52_BT_RX_BUF_ADDR,
   584	                          (uintptr_t)SF32LB52_BT_RX_BUF_ADDR +
   585	                          sizeof(*rx_ring));
   586	
   587	          env->rx_count++;
   588	
   589	          adv_ipc_diag = env->adv_ipc_diag_pending;
   590	
   591	          leave_critical_section(flags);
   592	
   593	          if (adv_ipc_diag)
   594	            {
   595	              sf32lb52_bt_adv_ipc_diag_dump("rx", env->data_buf, read_len,
   596	                                            read_len > 32 ? 32 : read_len);
   597	              syslog(LOG_INFO,
   598	                     "ov_ble_adv_ipc_diag: rx ring len=%lu rd_before=%08lx rd_after=%08lx wr=%08lx\n",
   599	                     (unsigned long)read_len,
   600	                     (unsigned long)rd_before,
   601	                     (unsigned long)env->rx_read_idx_mirror,
   602	                     (unsigned long)wr_ptr);
   603	            }
   604	
   605	        #if SF32LB52_BT_TRACE
   606	             syslog(LOG_INFO,
   607	               "sf32lb52 bt rx drain: len=%lu local=%08lx wr=%08lx\n",
   608	               (unsigned long)read_len,
   609	               (unsigned long)env->rx_read_idx_mirror,
   610	               (unsigned long)wr_ptr);
   611	        #endif
   612	
   613	          if (env->notify_host == NULL)
   614	            {
   615	              continue;
   616	            }
   617	
   618	          ret = env->notify_host(env->data_buf, read_len);
   619	          if (adv_ipc_diag)
   620	            {
   621	              syslog(LOG_INFO,
   622	                     "ov_ble_adv_ipc_diag: rx notify_host ret=%d len=%lu\n",
   623	                     ret, (unsigned long)read_len);
   624	            }
   625	
   626	          if (ret < 0)
   627	            {
   628	              syslog(LOG_ERR,
   629	                     "sf32lb52 bt rx deliver failed: ret=%d len=%u\n",
   630	                     ret, (unsigned int)read_len);
   631	            }
   632	        }
   633	
   634	      flags = enter_critical_section();
   635	      if (!env->rx_work_pending)
   636	        {
   637	          env->rx_worker_running = false;
   638	          leave_critical_section(flags);
   639	          break;
   640	        }
   641	
   642	      env->rx_work_pending = false;
   643	      leave_critical_section(flags);
   644	    }
   645	}
