   427	static bool sf32lb52_bt_adv_ipc_diag_cmd(const uint8_t *data, size_t len,
   428	                                         uint16_t *opcode)
   429	{
   430	  uint16_t value;
   431	
   432	  if (len < 4 || data[0] != SF32LB52_BT_H4_CMD ||
   433	      len != (size_t)data[3] + 4)
   434	    {
   435	      return false;
   436	    }
   437	
   438	  value = (uint16_t)data[1] | ((uint16_t)data[2] << 8);
   439	  if (value != SF32LB52_HCI_OP_LE_SET_ADV_PARAM &&
   440	      value != SF32LB52_HCI_OP_LE_SET_EXT_ADV_PARAM)
   441	    {
   442	      return false;
   443	    }
   444	
   445	  *opcode = value;
   446	  return true;
   447	}
