   449	static void sf32lb52_bt_adv_ipc_diag_dump(const char *direction,
   450	                                           const uint8_t *data,
   451	                                           size_t total_len,
   452	                                           size_t dump_len)
   453	{
   454	  static const char hex[] = "0123456789abcdef";
   455	  char bytes[3 * 259];
   456	  size_t i;
   457	  size_t pos = 0;
   458	
   459	  for (i = 0; i < dump_len && i < 259; i++)
   460	    {
   461	      if (i > 0)
   462	        {
   463	          bytes[pos++] = ' ';
   464	        }
   465	
   466	      bytes[pos++] = hex[data[i] >> 4];
   467	      bytes[pos++] = hex[data[i] & 0x0f];
   468	    }
   469	
   470	  bytes[pos] = '\0';
   471	  syslog(LOG_INFO, "ov_ble_adv_ipc_diag: %s len=%lu data=%s\n",
   472	         direction, (unsigned long)total_len, bytes);
   473	}
