   210	static size_t sf32lb52_bt_ring_data_len(uint32_t rd_ptr, uint32_t wr_ptr,
   211	                                        uint32_t buffer_size)
   212	{
   213	  uint32_t rd_idx = CB_GET_PTR_IDX(rd_ptr);
   214	  uint32_t wr_idx = CB_GET_PTR_IDX(wr_ptr);
   215	  uint32_t rd_mirror = CB_GET_PTR_MIRROR(rd_ptr);
   216	  uint32_t wr_mirror = CB_GET_PTR_MIRROR(wr_ptr);
   217	
   218	  if (rd_idx == wr_idx)
   219	    {
   220	      return rd_mirror == wr_mirror ? 0 : buffer_size;
   221	    }
   222	
   223	  if (wr_idx > rd_idx)
   224	    {
   225	      return wr_idx - rd_idx;
   226	    }
   227	
   228	  return buffer_size - (rd_idx - wr_idx);
   229	}
