   238	static uint32_t sf32lb52_bt_ring_advance(uint32_t ptr, size_t len,
   239	                                         uint32_t buffer_size)
   240	{
   241	  uint32_t idx = CB_GET_PTR_IDX(ptr);
   242	  uint32_t mirror = CB_GET_PTR_MIRROR(ptr);
   243	
   244	  idx += len;
   245	  if (idx >= buffer_size)
   246	    {
   247	      idx -= buffer_size;
   248	      mirror = ~mirror;
   249	    }
   250	
   251	  return CB_MAKE_PTR_IDX_MIRROR(idx, mirror);
   252	}
