   254	static size_t sf32lb52_bt_ring_copy(uint8_t *dst,
   255	                                    const struct circular_buf *rx_ring,
   256	                                    uint32_t rd_ptr,
   257	                                    size_t len)
   258	{
   259	  const uint8_t *pool = (const uint8_t *)(rx_ring + 1);
   260	  uint32_t rd_idx = CB_GET_PTR_IDX(rd_ptr);
   261	  size_t tail;
   262	
   263	  if (len == 0)
   264	    {
   265	      return 0;
   266	    }
   267	
   268	  tail = rx_ring->buffer_size - rd_idx;
   269	  if (tail >= len)
   270	    {
   271	      memcpy(dst, &pool[rd_idx], len);
   272	      return len;
   273	    }
   274	
   275	  memcpy(dst, &pool[rd_idx], tail);
   276	  memcpy(&dst[tail], pool, len - tail);
   277	  return len;
   278	}
