   361	static int sf32lb52_bt_wait_tx_idle(struct circular_buf *tx_ring)
   362	{
   363	  uint32_t start_time = HAL_GetTick();
   364	  uint32_t tick_count = 0;
   365	  uint32_t rd_ptr = 0;
   366	  uint32_t wr_ptr = 0;
   367	
   368	  while (sf32lb52_bt_tx_pending(tx_ring, &rd_ptr, &wr_ptr) > 0)
   369	    {
   370	      sf32lb52_bt_trigger_tx();
   371	
   372	      if (HAL_GetTick() != start_time)
   373	        {
   374	          tick_count++;
   375	          start_time = HAL_GetTick();
   376	        }
   377	
   378	      if (tick_count >= 100)
   379	        {
   380	          syslog(LOG_ERR,
   381	                 "sf32lb52 bt tx busy: rd=%08lx wr=%08lx\n",
