 280	static size_t sf32lb52_bt_ring_write(struct circular_buf *tx_ring,
 281	                                     const uint8_t *src, size_t len)
 282	{
 283	  uint8_t *pool = (uint8_t *)(tx_ring + 1);
 284	  uint32_t wr_ptr = tx_ring->write_idx_mirror;
 285	  uint32_t wr_idx = CB_GET_PTR_IDX(wr_ptr);
 286	  size_t space;
 287	  size_t tail;
 288	
 289	  space = sf32lb52_bt_ring_space_len(tx_ring->read_idx_mirror,
 290	                                     wr_ptr,
 291	                                     tx_ring->buffer_size);
 292	  if (space == 0)
 293	    {
 294	      return 0;
 295	    }
 296	
 297	  if (len > space)
 298	    {
 299	      len = space;
 300	    }
 301	
 302	  tail = tx_ring->buffer_size - wr_idx;
 303	  if (tail >= len)
 304	    {
 305	      memcpy(&pool[wr_idx], src, len);
 306	      up_clean_dcache((uintptr_t)&pool[wr_idx],
 307	                      (uintptr_t)&pool[wr_idx] + len);
 308	    }
 309	  else
 310	    {
 311	      memcpy(&pool[wr_idx], src, tail);
 312	      memcpy(pool, &src[tail], len - tail);
 313	      up_clean_dcache((uintptr_t)&pool[wr_idx],
 314	                      (uintptr_t)&pool[wr_idx] + tail);
 315	      up_clean_dcache((uintptr_t)pool,
 316	                      (uintptr_t)pool + len - tail);
 317	    }
 318	
 319	  tx_ring->write_idx_mirror = sf32lb52_bt_ring_advance(wr_ptr, len,
 320	                                                       tx_ring->buffer_size);
 321	  up_clean_dcache((uintptr_t)tx_ring,
 322	                  (uintptr_t)tx_ring + sizeof(*tx_ring));
 323	  __DSB();
 324	
 325	  return len;
 326	}
