 996	      (struct circular_buf *)SF32LB52_BT_TX_BUF_ADDR;
 997	  uint32_t start_time;
 998	  uint32_t tick_count;
 999	  size_t written;
1000	  size_t remaining;
1001	  size_t offset;
1002	  size_t chunk;
1003	  size_t chunks;
1004	  uint32_t wr_ptr;
1005	  uint32_t diag_rd;
1006	  uint32_t diag_wr;
1007	  uint32_t diag_after_rd;
1008	  uint32_t diag_after_wr;
1009	  uint16_t diag_opcode;
1010	  bool adv_ipc_diag;
1011	  int ret;
1012	
1013	  if (data == NULL || len == 0)
1014	    {
1015	      return -EINVAL;
1016	    }
1017	
1018	  if (g_sf32lb52_bt_status != SF32LB52_BT_STATUS_ENABLED ||
1019	      !g_sf32lb52_bt_env.queue_open)
1020	    {
1021	      return -ENODEV;
1022	    }
1023	
1024	  offset = 0;
1025	  remaining = len;
1026	  start_time = HAL_GetTick();
1027	  tick_count = 0;
1028	  chunks = 0;
1029	  wr_ptr = 0;
1030	
1031	  adv_ipc_diag = sf32lb52_bt_adv_ipc_diag_cmd(data, len, &diag_opcode);
1032	  if (adv_ipc_diag)
1033	    {
1034	      irqstate_t flags;
1035	
1036	      flags = enter_critical_section();
1037	      g_sf32lb52_bt_env.adv_ipc_diag_opcode = diag_opcode;
1038	      g_sf32lb52_bt_env.adv_ipc_diag_pending = true;
1039	      leave_critical_section(flags);
1040	
1041	      sf32lb52_bt_adv_ipc_diag_dump("tx", data, len, len);
1042	    }
1043	
1044	  ret = sf32lb52_bt_wait_tx_idle(tx_ring);
1045	  if (adv_ipc_diag)
1046	    {
1047	      sf32lb52_bt_tx_pending(tx_ring, &diag_rd, &diag_wr);
1048	      syslog(LOG_INFO,
1049	             "ov_ble_adv_ipc_diag: tx initial_wait ret=%d rd=%08lx wr=%08lx\n",
1050	             ret, (unsigned long)diag_rd, (unsigned long)diag_wr);
1051	    }
1052	
1053	  if (ret < 0)
1054	    {
1055	      return ret;
1056	    }
1057	
1058	  while (remaining > 0)
1059	    {
1060	      irqstate_t flags;
1061	
1062	      chunk = sf32lb52_bt_tx_chunk_len(data, len, offset);
1063	
1064	      up_invalidate_dcache((uintptr_t)SF32LB52_BT_TX_BUF_ADDR,
1065	                           (uintptr_t)SF32LB52_BT_TX_BUF_ADDR +
1066	                           sizeof(*tx_ring));
1067	
1068	      flags = enter_critical_section();
1069	      if (adv_ipc_diag)
1070	        {
1071	          diag_rd = tx_ring->read_idx_mirror;
1072	          diag_wr = tx_ring->write_idx_mirror;
1073	        }
1074	
1075	      written = sf32lb52_bt_ring_write(tx_ring, data + offset, chunk);
1076	      if (adv_ipc_diag && written > 0)
1077	        {
1078	          wr_ptr = tx_ring->write_idx_mirror;
1079	        }
1080	
1081	      leave_critical_section(flags);
1082	
1083	      if (adv_ipc_diag && written > 0)
1084	        {
1085	          sf32lb52_bt_tx_pending(tx_ring, &diag_after_rd,
1086	                                 &diag_after_wr);
1087	          syslog(LOG_INFO,
1088	                 "ov_ble_adv_ipc_diag: tx publish opcode=0x%04x before_rd=%08lx before_wr=%08lx after_rd=%08lx after_wr=%08lx\n",
1089	                 diag_opcode,
1090	                 (unsigned long)diag_rd, (unsigned long)diag_wr,
1091	                 (unsigned long)diag_after_rd,
1092	                 (unsigned long)diag_after_wr);
1093	        }
1094	
1095	      if (written == 0)
1096	        {
1097	          if (HAL_GetTick() != start_time)
1098	            {
1099	              tick_count++;
1100	              start_time = HAL_GetTick();
1101	            }
1102	
1103	          if (tick_count >= 10)
1104	            {
1105	              syslog(LOG_ERR,
1106	                     "sf32lb52 bt tx timeout: remaining=%lu\n",
1107	                     (unsigned long)remaining);
1108	              return -ETIMEDOUT;
1109	            }
1110	
1111	          continue;
1112	        }
1113	
1114	      offset += written;
1115	      remaining -= written;
1116	
1117	      __DSB();
1118	      wr_ptr = tx_ring->write_idx_mirror;
1119	      sf32lb52_bt_trigger_tx();
1120	      chunks++;
1121	    }
1122	
1123	#if SF32LB52_BT_TRACE
1124	  syslog(LOG_INFO,
1125	         "sf32lb52 bt tx publish: total=%u chunks=%lu wr=%08lx first=%02x\n",
1126	         len,
1127	         (unsigned long)chunks,
1128	         (unsigned long)wr_ptr,
1129	         data[0]);
1130	
1131	  sf32lb52_bt_log_tx_state(tx_ring, "queued", wr_ptr);
1132	#endif
1133	
1134	  if (data[0] == SF32LB52_BT_H4_CMD)
1135	    {
1136	      ret = sf32lb52_bt_wait_tx_idle(tx_ring);
1137	      if (adv_ipc_diag)
1138	        {
1139	          sf32lb52_bt_tx_pending(tx_ring, &diag_rd, &diag_wr);
1140	          syslog(LOG_INFO,
1141	                 "ov_ble_adv_ipc_diag: tx final_wait opcode=0x%04x ret=%d rd=%08lx wr=%08lx\n",
1142	                 diag_opcode, ret,
1143	                 (unsigned long)diag_rd, (unsigned long)diag_wr);
1144	        }
1145	
1146	      if (ret < 0)
1147	        {
1148	          return ret;
1149	        }
1150	    }
1151	
1152	  return OK;
1153	}
