 731	static int sf32lb52_bt_ensure_controller_enabled(uint16_t opcode)
 732	{
 733	  int ret;
 734	
 735	  ret = sf32lb52_bt_controller_enable();
 175	    int32_t result = -1;
 176	    uint8_t *pool;
 177	    uint32_t mask;
 178	    ipc_queue_t *queue;
 179	    int32_t offset;
 180	
 181	    if (!is_valid_handle(handle))
 182	    {
 183	        return result;
 184	    }
 185	
 186	    offset = IPC_QUEUE_HANDLE_2_OFFSET(handle);
 187	    queue = &ipc_ctx.queues[offset];
