   572	#ifdef CONFIG_ARMV8M_DCACHE
   573	void up_disable_dcache(void)
   574	{
   575	  struct
   576	    {
   577	      uint32_t ccsidr;
   578	      uint32_t ccr;
   579	      uint32_t sshift;
   580	      uint32_t wshift;
