   558	/****************************************************************************
   559	 * Name: up_disable_dcache
   560	 *
   561	 * Description:
   562	 *   Disable the D-Cache
   563	 *
   564	 * Input Parameters:
   565	 *   None
   566	 *
   567	 * Returned Value:
   568	 *   None
   569	 *
   570	 ****************************************************************************/
   571	
   572	#ifdef CONFIG_ARMV8M_DCACHE
   573	void up_disable_dcache(void)
   574	{
   575	  struct
   576	    {
   577	      uint32_t ccsidr;
   578	      uint32_t ccr;
   579	      uint32_t sshift;
   580	      uint32_t wshift;
   581	      uint32_t sw;
   582	      uint32_t sets;
   583	      uint32_t ways;
   584	      uint32_t tmpways;
   585	    } locals;
   586	
   587	  /* Disable the D-Cache */
   588	
   589	  locals.ccr = getreg32(NVIC_CFGCON);
   590	  locals.ccr &= ~NVIC_CFGCON_DC;
   591	  putreg32(locals.ccr, NVIC_CFGCON);
   592	  UP_MB();
   593	
   594	  /* Clean and invalidate the local variable cache. */
   595	
   596	  up_flush_dcache((uintptr_t)&locals, (uintptr_t)&locals + sizeof(locals));
   597	  UP_MB();
   598	
   599	  /* Get the characteristics of the D-Cache */
   600	
   601	  locals.ccsidr = getreg32(NVIC_CCSIDR);
   602	  locals.sets   = CCSIDR_SETS(locals.ccsidr);          /* (Number of sets) - 1 */
   603	  locals.sshift = CCSIDR_LSSHIFT(locals.ccsidr) + 4;   /* log2(cache-line-size-in-bytes) */
   604	  locals.ways   = CCSIDR_WAYS(locals.ccsidr);          /* (Number of ways) - 1 */
   605	
   606	  /* Calculate the bit offset for the way field in the DCCISW register by
   607	   * counting the number of leading zeroes.  For example:
   608	   *
   609	   *   Number of  Value of ways  Field
   610	   *   Ways       'ways'         Offset
   611	   *     2         1             31
   612	   *     4         3             30
   613	   *     8         7             29
   614	   *   ...
   615	   */
   616	
   617	  locals.wshift = arm_clz(locals.ways) & 0x1f;
   618	
   619	  UP_DSB();
   620	
   621	  /* Clean and invalidate the entire D-Cache */
   622	
   623	  do
   624	    {
   625	      locals.tmpways = locals.ways;
   626	
   627	      do
   628	        {
   629	          locals.sw = ((locals.tmpways << locals.wshift) |
   630	                       (locals.sets << locals.sshift));
   631	          putreg32(locals.sw, NVIC_DCCISW);
   632	        }
   633	      while (locals.tmpways--);
   634	    }
   635	  while (locals.sets--);
   636	
   637	  UP_MB();
   638	
   639	  l2cc_disable();
   640	}
