   845	  sf32lb52_bt_prepare_stack_nvds();
   846	  HAL_LCPU_ASSERT_INFO_clear();
   847	
   848	  ret = lcpu_power_on();
   849	  if (ret != 0)
   850	    {
   851	      return -EIO;
   852	    }
   853	
   854	  /* The L2H_MAILBOX (0x40002000) is on the LPSYS APB bus.  Its CxIER
   855	   * register is only writable when the LPSYS bus bridge is active.
   856	   * Wake the LCPU first so the bus bridge is powered, THEN open the
   857	   * IPC queue (which writes CxIER to unmask the mailbox RX interrupt).
   858	   * The SDK reference ipc_hw_enable_interrupt2() has the same
   859	   * HAL_HPAON_WakeCore() before the UNMASK call.
   860	   */
   861	
   862	  HAL_HPAON_WakeCore(CORE_ID_LCPU);
   863	  g_sf32lb52_bt_env.wake_held = true;
   864	
   865	  usleep(500000);
   866	
   867	  ret = ipc_queue_open(g_sf32lb52_bt_env.ipc_port);
   868	  if (ret < 0)
   869	    {
   870	      HAL_HPAON_CANCEL_LP_ACTIVE_REQUEST();
   871	      g_sf32lb52_bt_env.wake_held = false;
   872	      return ret;
   873	    }
   874	
   875	  /* Flush H2L TX ring to SRAM immediately after ipc_queue_open so
   876	   * LCPU sees the reset indices (read_idx=write_idx=0) before it
   877	   * tries to process any stale data from a previous session.
   878	   */
   879	  up_clean_dcache((uintptr_t)SF32LB52_BT_TX_BUF_ADDR,
   880	                  (uintptr_t)SF32LB52_BT_TX_BUF_ADDR +
   881	                  SF32LB52_BT_TX_BUF_SIZE);
   882	  __DSB();
   883	
   884	  /* After every lcpu_power_on(), LCPU resets its TX ring write pointer
   885	   * (write_idx_mirror) to 0 and writes its own boot responses into the
   886	   * ring.  HCPU's read pointer (read_idx_mirror) may still hold the
   887	   * non-zero value from the previous session -- dirty in DCache or
   888	   * stored in SRAM.  If we do not synchronise them:
   889	   *
   890	   *   circular_buf_data_len() = wrap(write_idx - read_idx)
   891	   *
   892	   * returns a large garbage value, and LCPU's fresh boot events
   893	   * plus ring garbage all replay as "new" HCI responses.  These
   894	   * ghost events are consumed by the host as replies to real commands,
   895	   * so HCI_Reset (0x0c01) is never actually executed by the controller,
   896	   * and bt_le_adv_start later gets "Command Disallowed" (0x07).
   897	   *
   898	   * Fix: flush DCache to write back any dirty read_idx and to load
   899	   * LCPU's current write_idx from SRAM, then advance read_idx to
   900	   * write_idx (discard ALL pending LCPU boot data), then clean the
   901	   * DCache so LCPU sees the updated read pointer in SRAM.
   902	   */
   903	
   904	  {
