+  char bytes[3 * 259];
+  size_t i;
+  size_t pos = 0;
+
+  for (i = 0; i < dump_len && i < 259; i++)
+    {
+      if (i > 0)
+        {
+          bytes[pos++] = ' ';
+        }
+
+      bytes[pos++] = hex[data[i] >> 4];
+      bytes[pos++] = hex[data[i] & 0x0f];
+    }
+
+  bytes[pos] = '\0';
