2613	static void hci_cmd_complete(struct bt_dev *hdev, struct net_buf *buf)
2614	{
2615		struct bt_hci_evt_cmd_complete *evt;
2616		uint8_t status, ncmd;
2617		uint16_t opcode;
2618	
2619		evt = net_buf_pull_mem(buf, sizeof(*evt));
2620		ncmd = evt->ncmd;
2621		opcode = sys_le16_to_cpu(evt->opcode);
2622	
2623		LOG_DBG("opcode 0x%04x %s", opcode, bt_hci_opcode_to_str(opcode));
2624	
2625		/* All command return parameters have a 1-byte status in the
2626		 * beginning, so we can safely make this generalization.
2627		 */
2628		status = buf->data[0];
2629	
2630		/* HOST_NUM_COMPLETED_PACKETS should not generate a response under normal operation.
2631		 * The generation of this command ignores `ncmd_sem`, so should not be given here.
2632		 */
2633		if (opcode == BT_HCI_OP_HOST_NUM_COMPLETED_PACKETS) {
2634			LOG_WRN("Unexpected HOST_NUM_COMPLETED_PACKETS, status 0x%02x %s",
2635				status, bt_hci_err_to_str(status));
2636			return;
2637		}
2638	
2639		hci_cmd_done(hdev, opcode, status, buf);
2640	
2641		/* Allow next command to be sent */
2642		if (ncmd) {
2643			k_sem_give(&hdev->ncmd_sem);
2644			bt_tx_irq_raise(hdev);
2645		}
2646	}
