5027	/* Return `true` if a command was processed/sent */
5028	static bool process_pending_cmd(struct bt_dev *hdev, k_timeout_t timeout)
5029	{
5030		if (!k_fifo_is_empty(&hdev->cmd_tx_queue)) {
5031			if (k_sem_take(&hdev->ncmd_sem, timeout) == 0) {
5032				hci_core_send_cmd(hdev);
5033				return true;
5034			}
5035		}
5036	
5037		return false;
5038	}
