5040	static void tx_work_handler(struct k_work *work)
5041	{
5042		struct bt_dev *hdev = CONTAINER_OF(work, struct bt_dev, tx_work);
5043	
5044		LOG_DBG("dev:%d, TX process start", hdev->dev_id);
5045		if (process_pending_cmd(hdev, K_NO_WAIT)) {
5046			/* If we processed a command, let the scheduler run before
5047			 * processing another command (or data).
5048			 */
5049			bt_tx_irq_raise(hdev);
5050			return;
5051		}
5052	
5053		/* Hand over control to conn to process pending data */
5054		if (IS_ENABLED(CONFIG_BT_CONN_TX)) {
5055			bt_conn_tx_processor(hdev);
5056		}
