2648	static void hci_cmd_status(struct bt_dev *hdev, struct net_buf *buf)
2649	{
2650		struct bt_hci_evt_cmd_status *evt;
2651		uint16_t opcode;
2652		uint8_t ncmd;
2653	
2654		evt = net_buf_pull_mem(buf, sizeof(*evt));
2655		opcode = sys_le16_to_cpu(evt->opcode);
2656		ncmd = evt->ncmd;
2657	
2658		LOG_DBG("opcode 0x%04x %s", opcode, bt_hci_opcode_to_str(opcode));
2659	
2660		hci_cmd_done(hdev, opcode, evt->status, buf);
2661	
2662		/* Allow next command to be sent */
2663		if (ncmd) {
2664			k_sem_give(&hdev->ncmd_sem);
2665			bt_tx_irq_raise(hdev);
2666		}
