3131	/** @brief Get HCI event flags.
3132	 *
3133	 * Helper for the HCI driver to get HCI event flags that describes rules that.
3134	 * must be followed.
3135	 *
3136	 * @param evt HCI event code.
3137	 *
3138	 * @return HCI event flags for the specified event.
3139	 */
3140	static inline uint8_t bt_hci_evt_get_flags(uint8_t evt)
3141	{
3142		switch (evt) {
3143		case BT_HCI_EVT_DISCONN_COMPLETE:
3144			return BT_HCI_EVT_FLAG_RECV | BT_HCI_EVT_FLAG_RECV_PRIO;
3145			/* fallthrough */
3146	#if defined(CONFIG_BT_CONN) || defined(CONFIG_BT_ISO)
3147		case BT_HCI_EVT_NUM_COMPLETED_PACKETS:
3148	#if defined(CONFIG_BT_CONN)
3149		case BT_HCI_EVT_DATA_BUF_OVERFLOW:
3150			__fallthrough;
3151	#endif /* defined(CONFIG_BT_CONN) */
3152	#endif /* CONFIG_BT_CONN ||  CONFIG_BT_ISO */
3153		case BT_HCI_EVT_CMD_COMPLETE:
3154		case BT_HCI_EVT_CMD_STATUS:
3155			return BT_HCI_EVT_FLAG_RECV_PRIO;
3156		default:
3157			return BT_HCI_EVT_FLAG_RECV;
3158		}
3159	}
