3180	static void hci_core_send_cmd(struct bt_dev *hdev)
3181	{
3182		struct net_buf *buf;
3183		int err;
3184	
3185		/* Get next command */
3186		LOG_DBG("dev:%d, fetch cmd", hdev->dev_id);
3187		buf = k_fifo_get(&hdev->cmd_tx_queue, K_NO_WAIT);
3188		BT_ASSERT(buf);
3189	
3190		/* Clear out any existing sent command */
3191		if (hdev->sent_cmd) {
3192			LOG_ERR("Uncleared pending sent_cmd");
3193			net_buf_unref(hdev->sent_cmd);
3194			hdev->sent_cmd = NULL;
3195		}
3196	
3197		hdev->sent_cmd = net_buf_ref(buf);
3198	
3199		LOG_DBG("Sending command 0x%04x %s (buf %p) to driver", cmd(buf)->opcode, bt_hci_opcode_to_str(cmd(buf)->opcode), buf);
3200	
3201		err = bt_send(hdev, buf);
3202		if (err) {
3203			LOG_ERR("Unable to send to driver (err %d)", err);
3204			k_sem_give(&hdev->ncmd_sem);
3205			hci_cmd_done(hdev, cmd(buf)->opcode, BT_HCI_ERR_UNSPECIFIED, buf);
3206			net_buf_unref(buf);
3207			bt_tx_irq_raise(hdev);
3208		}
3209	}
