  4262	static int bt_recv_unsafe(struct bt_dev *hdev, struct net_buf *buf)
  4263	{
  4264		bt_monitor_send(bt_monitor_opcode(buf), buf->data, buf->len);
  4265	
  4266		LOG_DBG("buf %p len %u", buf, buf->len);
  4267	
  4268		switch (bt_buf_get_type(buf)) {
  4269	#if defined(CONFIG_BT_CONN)
  4270		case BT_BUF_ACL_IN:
  4271			rx_queue_put(hdev, buf);
  4272			return 0;
  4273	#endif /* BT_CONN */
  4274		case BT_BUF_EVT:
  4275		{
  4276			struct bt_hci_evt_hdr *hdr = (void *)buf->data;
  4277			uint8_t evt_flags = bt_hci_evt_get_flags(hdr->evt);
  4278	
  4279			if (evt_flags & BT_HCI_EVT_FLAG_RECV_PRIO) {
  4280				hci_event_prio(hdev, buf);
  4281			}
  4282	
  4283			if (evt_flags & BT_HCI_EVT_FLAG_RECV) {
  4284				rx_queue_put(hdev, buf);
  4285			}
  4286	
  4287			return 0;
  4288		}
  4289	#if defined(CONFIG_BT_ISO)
  4290		case BT_BUF_ISO_IN:
  4291			rx_queue_put(hdev, buf);
  4292			return 0;
  4293	#endif /* CONFIG_BT_ISO */
  4294		default:
  4295			LOG_ERR("Invalid buf type %u", bt_buf_get_type(buf));
  4295			LOG_ERR("Invalid buf type %u", bt_buf_get_type(buf));
  4296			net_buf_unref(buf);
  4297			return -EINVAL;
  4298		}
  4299	}
