   458	int bt_hci_cmd_send(struct bt_dev *hdev, uint16_t opcode, struct net_buf *buf)
   459	{
   460		if (!buf) {
   461			buf = bt_hci_cmd_create(opcode, 0);
   462			if (!buf) {
   463				return -ENOBUFS;
   464			}
   465		}
   466	
   467		if (hci_cmd_is_quarantined(hdev)) {
   468			net_buf_unref(buf);
   469			return -EIO;
   470		}
   471	
   472		LOG_DBG("opcode 0x%04x %s len %u", opcode, bt_hci_opcode_to_str(opcode), buf->len);
   473	
   474		/* Host Number of Completed Packets can ignore the ncmd value
   475		 * and does not generate any cmd complete/status events.
   476		 */
   477		if (opcode == BT_HCI_OP_HOST_NUM_COMPLETED_PACKETS) {
   478			int err;
   479	
   480			err = bt_send(hdev, buf);
   481			if (err) {
   482				LOG_ERR("Unable to send to driver (err %d)", err);
   483				net_buf_unref(buf);
   484			}
   485	
   486			return err;
   487		}
   488	
   489		if (hci_cmd_enqueue(hdev, buf)) {
   490			net_buf_unref(buf);
   491			return -EIO;
   492		}
   493	
   494		bt_tx_irq_raise(hdev);
   495	
   496		return 0;
   497	}
