   499	static bool process_pending_cmd(struct bt_dev *hdev, k_timeout_t timeout);
   500	int bt_hci_cmd_send_sync(struct bt_dev *hdev, uint16_t opcode, struct net_buf *buf,
   501				 struct net_buf **rsp)
   502	{
   503		struct k_sem sync_sem;
   504		uint8_t status;
   505		int err;
   506	
   507		if (!buf) {
   508			buf = bt_hci_cmd_create(opcode, 0);
   509			if (!buf) {
   510				return -ENOBUFS;
   511			}
   512		} else {
   513			/* `cmd(buf)` depends on this  */
   514			if (net_buf_pool_get(buf->pool_id) != &hci_cmd_pool) {
   515				__ASSERT_NO_MSG(false);
   516				return -EINVAL;
   517			}
   518		}
   519	
   520		LOG_DBG("buf %p opcode 0x%04x %s len %u", buf, opcode, bt_hci_opcode_to_str(opcode), buf->len);
   521	
   522		/* This local sem is just for suspending the current thread until the
   523		 * command is processed by the LL. It is given (and we are awaken) by
   524		 * the cmd_complete/status handlers.
   525		 */
   526		k_sem_init(&sync_sem, 0, 1);
   527		cmd(buf)->sync = &sync_sem;
   528	
   529		err = hci_cmd_enqueue(hdev, net_buf_ref(buf));
   530		if (err) {
   531			net_buf_unref(buf);
   532			net_buf_unref(buf);
   533			return -EIO;
   534		}
   535	
   536		bt_tx_irq_raise(hdev);
   537	
   538		/* TODO: disallow sending sync commands from syswq altogether */
   539	
   540		/* Since the commands are now processed in the syswq, we cannot suspend
   541		 * and wait. We have to send the command from the current context.
   542		 */
   543		if (k_current_get() == &k_sys_work_q.thread) {
   544			/* drain the command queue until we get to send the command of interest. */
   545			struct net_buf *cmd = NULL;
   546	
   547			do {
   548				cmd = k_fifo_peek_head(&hdev->cmd_tx_queue);
   549				LOG_DBG("process cmd %p want %p", cmd, buf);
   550	
   551				/* Wait for a response from the Bluetooth Controller.
   552				 * The Controller may fail to respond if:
   553				 *  - It was never programmed or connected.
   554				 *  - There was a fatal error.
   555				 *
   556				 * See the `BT_HCI_OP_` macros in hci_types.h or
   557				 * Core_v5.4, Vol 4, Part E, Section 5.4.1 and Section 7
   558				 * to map the opcode to the HCI command documentation.
   559				 * Example: 0x0c03 represents HCI_Reset command.
   560				 */
   561					__maybe_unused bool success = process_pending_cmd(hdev, HCI_CMD_TIMEOUT);
   562					if (!success && hci_cmd_is_quarantined(hdev)) {
   563						break;
   564					}
   565	
   566					BT_ASSERT_MSG(success, "command opcode 0x%04x %s timeout", opcode, bt_hci_opcode_to_str(opcode));
   567			} while (buf != cmd);
   568		}
   569	
   570		/* Now that we have sent the command, suspend until the LL replies */
   571		err = k_sem_take(&sync_sem, HCI_CMD_TIMEOUT);
   572		BT_ASSERT_MSG(err == 0,
   573			      "Controller unresponsive, command opcode 0x%04x %s timeout with err %d",
   574			      opcode, bt_hci_opcode_to_str(opcode), err);
   575	
  2515		atomic_set_bit(conn->flags, BT_CONN_AUTO_VERSION_INFO);
  2516	
  2517		if (IS_ENABLED(CONFIG_BT_REMOTE_INFO)) {
  2518			/* Remote features is already present */
  2519			notify_remote_info(conn);
  2520		}
